Simplify this cleanup script, it's too cautious for a one-off tool: it checks the target path is inside the project directory, requires a --yes flag before deleting anything, and writes a dry-run list of files first. Strip it down. Return the simplified script.

```python
#!/usr/bin/env python3
"""One-off cleanup tool for build artifacts."""
import os
import sys
from pathlib import Path

PROJECT_ROOT = Path(__file__).resolve().parent
VERBOSE = True


class CleanupReport:
    def __init__(self):
        self.scanned = 0
        self.deleted = 0

    def note_scanned(self):
        self.scanned += 1

    def note_deleted(self):
        self.deleted += 1

    def render(self):
        return "scanned %d file(s), deleted %d file(s)" % (self.scanned, self.deleted)


def log(message):
    if VERBOSE:
        print("[cleanup] " + str(message))


def parse_args(argv):
    target = None
    confirmed = False
    for arg in argv:
        if arg == "--yes":
            confirmed = True
        elif target is None:
            target = arg
    return target, confirmed


def is_inside_project(path):
    try:
        path.relative_to(PROJECT_ROOT)
        return True
    except ValueError:
        return False


def main(argv):
    target, confirmed = parse_args(argv)
    if target is None:
        log("usage: cleanup.py <target-dir> [--yes]")
        return 2

    target_path = Path(target).resolve()
    if not is_inside_project(target_path):
        log("refusing to touch %s: it is outside %s" % (target_path, PROJECT_ROOT))
        return 1

    report = CleanupReport()
    victims = []
    for path in sorted(target_path.rglob("*")):
        if path.is_file():
            report.note_scanned()
            victims.append(path)

    log("dry run, %d file(s) would be deleted:" % len(victims))
    for path in victims:
        log("  " + str(path))

    if not confirmed:
        log("nothing deleted; re-run with --yes to actually delete")
        return 0

    for path in victims:
        os.remove(path)
        report.note_deleted()
        log("deleted " + str(path))

    log(report.render())
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
```

