  "contributes": { "dataSources": [{ "id": "opportunities", "displayName": "Opportunities", "timeoutMs": 120000,
    "configSchema": { "type": "object", "required": ["stage"],
      "properties": { "stage": { "enum": ["open","won","lost"] } } } }] },
  "configuration": { "type": "object", "required": ["instanceUrl"], "properties": {
