## 3. Manifest schema

The manifest is `plugin.json` at the package root. The manifest format has its own version (`manifestVersion`), separate from the API version.

### 3.1 Example

```json
{
  "$schema": "https://plugins.corp.internal/schemas/manifest-1.json",
  "manifestVersion": 1,
  "id": "finance.gl-connector",
  "publisher": "finance",
  "version": "1.4.2",
  "displayName": "General Ledger Connector",
  "description": "Query GL balances and journal entries.",
  "owners": ["finance-platform@corp.example"],
  "repository": "https://git.corp.internal/finance/gl-connector",

  "engines": { "hostApi": "^1.2.0" },
  "runtime": { "type": "node", "version": ">=22", "entry": "dist/index.js" },

  "activation": ["onContribution:dataSource/ledger"],

  "contributes": {
    "dataSources": [
      {
        "id": "ledger",
        "contract": "dataSource@1",
        "displayName": "GL Ledger",
        "configSchema": "schemas/ledger-config.schema.json"
      }
    ],
    "exporters": [
      {
        "id": "gl-xlsx",
        "contract": "exporter@1",
        "displayName": "GL Workbook",
        "optionsSchema": "schemas/xlsx-options.schema.json"
      }
    ]
  },

  "dependsOn": {
    "services": [{ "ref": "core.fx-rates/rates", "contract": "service@1", "optional": false }]
  },

  "permissions": {
    "network": [{ "host": "gl.corp.internal", "ports": [443], "methods": ["GET", "POST"] }],
    "secrets": [{ "name": "gl-api-token", "mode": "inject" }],
    "storage": { "kv": { "quotaMB": 10 } },
    "data": { "datasets": "none" },
    "events": []
  },

  "limits": { "memoryMB": 512, "callTimeoutMs": 60000, "concurrency": 4 },

  "config": { "schema": "schemas/plugin-config.schema.json" },
  "state": { "snapshotSchemaVersion": 2 }
}
```

