## 6. API surface (Host API 1.0)

### 6.1 Server entry point

```ts
// dist/server.js
import { definePlugin } from "@report/plugin-sdk";

export default definePlugin({
  async activate(ctx) {
    return { dataSources: { soql: new SoqlSource(ctx) } };
  },
  async deactivate(reason) { /* close pools, flush */ },
});
```

```ts
export interface PluginModule {
  /** Must return exactly the contribution IDs declared in the manifest, or activation fails. */
  activate(ctx: PluginContext): Promise<Contributions> | Contributions;
  deactivate?(reason: DeactivateReason): Promise<void> | void;               // 5s budget
  /** Reload handoff: JSON, at most 1 MiB. The new instance receives it as ctx.previousState. */
  exportState?(): Promise<JsonValue> | JsonValue;
  health?(): Promise<HealthReport> | HealthReport;                           // 2s budget
  onSettingsChanged?(settings: JsonObject): Promise<void> | void;            // no reload needed
}

export type DeactivateReason = "unload" | "reload" | "disable" | "idle" | "shutdown" | "dependency"; // open enum
export interface HealthReport { status: "ok" | "degraded" | "failing"; message?: string }

export interface Contributions {
  dataSources?: Record<string, DataSource>;
  transforms?: Record<string, Transform>;
  exporters?: Record<string, Exporter>;
  actions?: Record<string, Action>;
  services?: Record<string, ServiceImpl>;
}
```

### 6.2 Contexts

`PluginContext` lives for the whole instance, and each instance belongs to one tenant. `Call` is created for each invocation. APIs that act for a user exist **only on `Call`**, so a plugin can't act as a user outside a live call.

```ts
export interface PluginContext {
  readonly plugin: { id: string; version: string };
  readonly host: { apiVersion: string; capabilities: ReadonlySet<string> };
  readonly tenant: { id: string };
  readonly settings: JsonObject;                // validated against settingsSchema
  readonly previousState?: JsonValue;           // set only on reload
  readonly log: Logger;                         // structured; secrets redacted by host
  readonly metrics: Metrics;                    // counter/histogram/gauge, names auto-prefixed
  readonly secrets: Secrets;                    // declared + granted names only
  readonly storage: KeyValueStore;              // tenant+plugin scoped, quota-enforced
  readonly http: HttpClient;                    // fetch-compatible, egress allowlist enforced
  readonly services: ServiceClient;             // declared dependencies only
  readonly tmpDir: string;                      // wiped on unload
}

export interface Call {
  readonly signal: AbortSignal;                 // fires on cancel or deadline
  readonly deadline: number;                    // epoch ms
  readonly traceId: string;
  readonly user?: UserInfo;                     // shape limited by permissions.user
  readonly datasets: DatasetClient;             // requires permissions.datasets = "read"; runs as the call's user
  readonly log: Logger;                         // pre-tagged with traceId
  progress(fraction: number, message?: string): void;
}

export interface UserInfo { id: string; locale: string; timeZone: string; displayName?: string; email?: string }

export interface Secrets {
  get(name: string): Promise<{ value: string; version: string }>;  // for oauth2: a fresh access token
}

export interface KeyValueStore {
  get(key: string): Promise<{ value: JsonValue; revision: number } | undefined>;
  put(key: string, value: JsonValue, opts?: { ttlSec?: number }): Promise<number>;
  compareAndSet(key: string, value: JsonValue, expectedRevision: number | null): Promise<boolean>; // leases/locks
  delete(key: string): Promise<void>;
  list(prefix: string, cursor?: string): Promise<{ keys: string[]; cursor?: string }>;
}

export interface ServiceClient {
  call(ref: `${string}/${string}`, method: string, params: JsonValue, opts?: { signal?: AbortSignal }): Promise<JsonValue>;
}

export interface DatasetClient {
  query(ref: DatasetRef, request: QueryRequest): AsyncIterable<RecordBatch>; // host applies RLS
}
```

### 6.3 Contribution interfaces

```ts
interface ContributionBase<C> {
  /** Called when a stored config has configVersion < the manifest's. Pure function, no I/O. */
  migrateConfig?(fromVersion: number, config: JsonObject): C;
  /** Semantic checks only. The host has already validated config against configSchema. */
  validateConfig?(config: C, call: Call): Promise<Issue[]>;
}
export interface Issue { path: string; message: string; severity: "error" | "warning" }

// ---- Data sources
export interface DataSource<C = JsonObject> extends ContributionBase<C> {
  testConnection(config: C, call: Call): Promise<{ ok: boolean; message?: string }>;
  listDatasets(config: C, call: Call): Promise<DatasetInfo[]>;
  getSchema(config: C, dataset: string, call: Call): Promise<Schema>;
  /** If the source declares pushdownFilters/pushdownLimit, it MUST apply them completely (the conformance suite checks this). */
  query(config: C, request: QueryRequest, call: Call): AsyncIterable<RecordBatch>;
}
export interface DatasetInfo { name: string; displayName?: string; description?: string }
export interface QueryRequest {
  dataset: string;
  columns?: string[];
  filters?: Filter[];          // AND-combined; sent only if pushdownFilters is declared
  limit?: number;              // sent only if pushdownLimit is declared
}
export type Filter =
  | { column: string; op: "eq" | "neq" | "lt" | "lte" | "gt" | "gte"; value: Scalar }
  | { column: string; op: "in"; values: Scalar[] }
  | { column: string; op: "between"; low: Scalar; high: Scalar }
  | { column: string; op: "isNull" | "notNull" };        // open union: unknown op -> NOT_SUPPORTED

// ---- Transforms
export interface Transform<C = JsonObject> extends ContributionBase<C> {
  /** Throw ConfigError when config is incompatible with the input schema. */
  outputSchema(config: C, input: Schema, call: Call): Promise<Schema>;
  apply(config: C, input: AsyncIterable<RecordBatch>, call: Call): AsyncIterable<RecordBatch>;
}

// ---- Exporters
export interface Exporter<C = JsonObject> extends ContributionBase<C> {
  export(config: C, report: ReportSnapshot, call: Call): AsyncIterable<Uint8Array>;
}
export interface ReportSnapshot {
  id: string; title: string; generatedAt: string; parameters: JsonObject;
  sections: Section[];
}
export type Section =
  | { kind: "table"; title?: string; dataset: DatasetHandle }
  | { kind: "text"; markdown: string }
  | { kind: "visualization"; title?: string; ref: string; renderPng(opts: { width: number; height: number; scale?: number }): Promise<Uint8Array> };
export interface DatasetHandle { schema: Schema; rowCount?: number; batches(): AsyncIterable<RecordBatch> }

// ---- Actions (at-least-once delivery: use idempotencyKey)
export interface Action<C = JsonObject> extends ContributionBase<C> {
  execute(config: C, event: ActionEvent, call: Call): Promise<ActionResult>;
}
export interface ActionEvent {
  type: "report.scheduled" | "report.published" | "threshold.breached" | "manual"; // open enum
  reportId: string; occurredAt: string; idempotencyKey: string; payload: JsonObject;
}
export type ActionResult =
  | { status: "succeeded"; message?: string }
  | { status: "failed"; message: string }                  // not retried
  | { status: "retry"; message?: string; retryAfterMs?: number }; // host retries with backoff, max 5

// ---- Services (plugin-to-plugin, JSON only, validated against methodsSchema)
export type ServiceImpl = Record<string, (params: JsonValue, call: Call) => Promise<JsonValue>>;

// ---- Data model
export type RecordBatch = import("apache-arrow").RecordBatch;
export type Schema = import("apache-arrow").Schema;
```

