      "oauth2": {
        "authorizationUrl": "https://login.salesforce.com/services/oauth2/authorize",
        "tokenUrl": "https://login.salesforce.com/services/oauth2/token",
        "scopes": ["api", "refresh_token"]
      }
    }],
    "storage": { "kvQuotaMb": 10, "tmpQuotaMb": 100 },
    "datasets": "none",
    "user": "id"
  },
  "resources": { "memoryMb": 512, "cpu": 1, "invocationTimeoutMs": 120000, "maxConcurrency": 8 },
  "lifecycle": { "activation": "lazy", "idleShutdownSec": 300 },
  "dependencies": { "platform.oauth-broker": "^1.0.0" }
}
