## 6. API surface (Host API 1.0)

### 6.1 Server entry point

```ts
import { definePlugin } from "@report/plugin-sdk";

export default definePlugin({
  async activate(ctx) { return { dataSources: { soql: new SoqlSource(ctx) } }; },
  async deactivate(reason) { /* close pools */ },
});

export interface PluginModule {
  /** Must return exactly the contribution IDs in the manifest, or activation fails. 15s budget. */
  activate(ctx: PluginContext): Promise<Contributions> | Contributions;
  deactivate?(reason: DeactivateReason): Promise<void> | void;         // 5s budget
  exportState?(): Promise<JsonValue> | JsonValue;                      // reload handoff, ≤1 MiB
  health?(): Promise<HealthReport> | HealthReport;                     // 2s budget
  onSettingsChanged?(settings: JsonObject): Promise<void> | void;      // avoids a reload
}
export type DeactivateReason = "unload" | "reload" | "disable" | "idle" | "shutdown" | "dependency"; // open
export interface HealthReport { status: "ok" | "degraded" | "failing"; message?: string }
export interface Contributions {
  dataSources?: Record<string, DataSource>;
  transforms?: Record<string, Transform>;
  exporters?: Record<string, Exporter>;
  actions?: Record<string, Action>;
  services?: Record<string, ServiceImpl>;
}
```

### 6.2 Contexts

`PluginContext` lives as long as the plugin instance, and each instance belongs to one tenant. `Call` exists for a single invocation. **User-scoped APIs exist only on `Call`**, so a plugin can't act as a user outside a live call.

```ts
export interface PluginContext {
  readonly plugin: { id: string; version: string };
  readonly host: { apiVersion: string; capabilities: ReadonlySet<string> };
  readonly tenant: { id: string };
  readonly settings: JsonObject;          // validated against settingsSchema
  readonly previousState?: JsonValue;     // only on reload
  readonly log: Logger;                   // secrets redacted by host
  readonly metrics: Metrics;              // names auto-prefixed
  readonly secrets: Secrets;              // declared + granted + bound only
  readonly storage: KeyValueStore;        // (tenant, plugin) scoped, quota-enforced
  readonly http: HttpClient;              // fetch-compatible, egress allowlist enforced
  readonly services: ServiceClient;       // declared dependencies only
  readonly tmpDir: string;                // wiped on unload
}

export interface Call {
  readonly signal: AbortSignal;           // cancel or deadline
  readonly deadline: number;              // epoch ms
  readonly traceId: string;
  readonly user?: UserInfo;               // shape limited by permissions.user
  readonly datasets: DatasetClient;       // needs permissions.datasets="read"; runs as call's user
  readonly log: Logger;
  progress(fraction: number, message?: string): void;
}

export interface UserInfo { id: string; locale: string; timeZone: string; displayName?: string; email?: string }
export interface Secrets { get(name: string): Promise<{ value: string; version: string }> } // oauth2 → fresh access token
export interface KeyValueStore {
  get(key: string): Promise<{ value: JsonValue; revision: number } | undefined>;
  put(key: string, value: JsonValue, opts?: { ttlSec?: number }): Promise<number>;
  compareAndSet(key: string, value: JsonValue, expectedRevision: number | null): Promise<boolean>;
  delete(key: string): Promise<void>;
  list(prefix: string, cursor?: string): Promise<{ keys: string[]; cursor?: string }>;
}
export interface ServiceClient {
  call(ref: `${string}/${string}`, method: string, params: JsonValue, opts?: { signal?: AbortSignal }): Promise<JsonValue>;
}
export interface DatasetClient { query(ref: DatasetRef, request: QueryRequest): AsyncIterable<RecordBatch> } // host applies RLS
```

### 6.3 Contribution interfaces

```ts
interface ContributionBase<C> {
  /** Called when a stored config's configVersion is below the manifest's. Pure function, no I/O. */
  migrateConfig?(fromVersion: number, config: JsonObject): C;
  /** Semantic checks only; the host has already validated the config against configSchema. */
  validateConfig?(config: C, call: Call): Promise<Issue[]>;
}
export interface Issue { path: string; message: string; severity: "error" | "warning" }

export interface DataSource<C = JsonObject> extends ContributionBase<C> {
  testConnection(config: C, call: Call): Promise<{ ok: boolean; message?: string }>;
  listDatasets(config: C, call: Call): Promise<{ name: string; displayName?: string; description?: string }[]>;
  getSchema(config: C, dataset: string, call: Call): Promise<Schema>;
  /** If pushdownFilters/pushdownLimit is declared, the plugin MUST apply them fully (checked by conformance). */
  query(config: C, request: QueryRequest, call: Call): AsyncIterable<RecordBatch>;
}
export interface QueryRequest { dataset: string; columns?: string[]; filters?: Filter[]; limit?: number }
export type Filter =                                   // AND-combined; open union
  | { column: string; op: "eq" | "neq" | "lt" | "lte" | "gt" | "gte"; value: Scalar }
  | { column: string; op: "in"; values: Scalar[] }
  | { column: string; op: "between"; low: Scalar; high: Scalar }
  | { column: string; op: "isNull" | "notNull" };

export interface Transform<C = JsonObject> extends ContributionBase<C> {
  outputSchema(config: C, input: Schema, call: Call): Promise<Schema>;   // throw ConfigError if incompatible
  apply(config: C, input: AsyncIterable<RecordBatch>, call: Call): AsyncIterable<RecordBatch>;
}

export interface Exporter<C = JsonObject> extends ContributionBase<C> {
  export(config: C, report: ReportSnapshot, call: Call): AsyncIterable<Uint8Array>;
}
export interface ReportSnapshot { id: string; title: string; generatedAt: string; parameters: JsonObject; sections: Section[] }
export type Section =
  | { kind: "table"; title?: string; dataset: { schema: Schema; rowCount?: number; batches(): AsyncIterable<RecordBatch> } }
  | { kind: "text"; markdown: string }
  | { kind: "visualization"; title?: string; ref: string;
      renderPng(o: { width: number; height: number; scale?: number }): Promise<Uint8Array> };

export interface Action<C = JsonObject> extends ContributionBase<C> {   // at-least-once delivery
  execute(config: C, event: ActionEvent, call: Call): Promise<ActionResult>;
}
export interface ActionEvent {
  type: "report.scheduled" | "report.published" | "threshold.breached" | "manual";  // open
  reportId: string; occurredAt: string; idempotencyKey: string; payload: JsonObject;
}
export type ActionResult =
  | { status: "succeeded"; message?: string }
  | { status: "failed"; message: string }                              // not retried
  | { status: "retry"; message?: string; retryAfterMs?: number };      // backoff, max 5 attempts

export type ServiceImpl = Record<string, (params: JsonValue, call: Call) => Promise<JsonValue>>; // validated vs methodsSchema
export type RecordBatch = import("apache-arrow").RecordBatch;
export type Schema = import("apache-arrow").Schema;
```

### 6.4 Browser entry point (visualizations)

```ts
import { defineBrowserPlugin } from "@report/plugin-sdk/browser";
export default defineBrowserPlugin({ visualizations: { "pipeline-funnel": FunnelViz } });

export interface Visualization<C = JsonObject> {
  migrateConfig?(fromVersion: number, config: JsonObject): C;
  mount(root: HTMLElement, init: VizInit<C>): VizInstance<C>;
}
export interface VizInit<C> {
  config: C;
  data: import("apache-arrow").Table;     // capped at maxRows by host
  theme: ThemeTokens;                     // light/dark tokens
  size: { width: number; height: number };
  locale: string; timeZone: string;
