/// <reference lib="dom" />
import type { RecordBatch, Schema as ArrowSchema, Table } from "apache-arrow";

export declare const HOST_API_VERSION: "1.0.0";

// ─── Shared value types ──────────────────────────────────────────────────────

export type JsonValue = string | number | boolean | null | JsonValue[] | { [key: string]: JsonValue };
export type ScalarValue = string | number | boolean | null;
export type TableSchema = ArrowSchema;

// ─── 1. Module entry point and lifecycle hooks ───────────────────────────────

/** Default export of the file named by manifest `main`. Wrap with `definePlugin` from the SDK. */
export interface PluginModule {
  /**
   * Load hook. Must register every contribution and service declared in the
   * manifest before resolving; undeclared registrations throw, missing ones
   * fail activation. Timeout: resources.timeouts.activationMs.
   */
  activate(ctx: PluginContext): Promise<void>;
  /**
   * Unload hook. `ctx.lifecycle.signal` is already aborted and in-flight
   * invocations are drained or cancelled. Timeout: resources.timeouts.deactivationMs,
   * after which the process is killed.
   */
  deactivate?(reason: DeactivateReason): Promise<void>;
  /** Runs once before `activate` when the installed version changes. Must be idempotent. */
  migrate?(ctx: MigrationContext): Promise<void>;
  /** Apply new plugin-level config in place. Absent, or "reload-required", triggers a reload. */
  onConfigChange?(next: JsonValue, previous: JsonValue): Promise<"applied" | "reload-required">;
  /** Polled every lifecycle.healthCheckIntervalSeconds. Absent: healthy while the process responds. */
  healthCheck?(): Promise<HealthStatus>;
}

export type DeactivateReason = "unload" | "reload" | "upgrade" | "disable" | "idle" | "shutdown";

export interface HealthStatus {
  status: "healthy" | "degraded" | "unhealthy";
  detail?: string;
}

export interface MigrationContext {
  /** null on first install. */
  readonly fromVersion: string | null;
  readonly toVersion: string;
  readonly storage: StorageScopes;
  readonly log: Logger;
}

// ─── 2. Plugin context (capabilities; no ambient authority) ──────────────────

export interface PluginContext {
  readonly plugin: { readonly id: string; readonly version: string };
  readonly host: HostInfo;
  /** Plugin-level config, validated against manifest config.schema. */
  readonly config: JsonValue;
  /** Aborted when deactivation starts. Pass to long-lived background work. */
  readonly lifecycle: { readonly signal: AbortSignal };
  readonly log: Logger;
  readonly metrics: Metrics;
  readonly storage: StorageScopes;
  readonly secrets: Secrets;
  readonly http: HttpClient;
  readonly services: Services;
  readonly contributions: ContributionRegistrar;
  readonly events: Events;
  /** Present only for names listed in permissions.experimentalApis. May change in any minor. @experimental */
  readonly experimental: Readonly<Record<string, unknown>>;
}

export interface HostInfo {
  /** Negotiated API version, e.g. "1.2.0". */
  readonly apiVersion: string;
  readonly hostVersion: string;
  /** Feature detection for additive features, e.g. "dataSource.orderByPushdown". */
  supports(feature: string): boolean;
}

export type LogFields = Record<string, ScalarValue>;

export interface Logger {
  debug(message: string, fields?: LogFields): void;
  info(message: string, fields?: LogFields): void;
  warn(message: string, fields?: LogFields): void;
  error(message: string, fields?: LogFields & { error?: unknown }): void;
  child(fields: LogFields): Logger;
}

/** Names are prefixed with `plugin_<id>_`. Max 1000 series per plugin; extra series are dropped and counted. */
export interface Metrics {
  counter(name: string, labels?: Record<string, string>): { add(value?: number): void };
  histogram(name: string, labels?: Record<string, string>): { record(value: number): void };
  gauge(name: string, labels?: Record<string, string>): { set(value: number): void };
}

export interface StorageScopes {
  /** Shared across workspaces. Requires "plugin" in permissions.storage.scopes. */
  readonly plugin: KeyValueStore;
  /** Scoped to the invocation's workspace. Requires "workspace" in permissions.storage.scopes. */
  workspace(inv: InvocationContext): KeyValueStore;
}

export interface KeyValueStore {
  get<T extends JsonValue = JsonValue>(key: string): Promise<{ value: T; version: number } | undefined>;
  /** `ifVersion` gives compare-and-set; required for correctness when instances.max > 1 or during blue-green reload. */
  set(key: string, value: JsonValue, options?: { ttlSeconds?: number; ifVersion?: number }): Promise<{ version: number }>;
  delete(key: string, options?: { ifVersion?: number }): Promise<boolean>;
  list(prefix?: string, options?: { cursor?: string; limit?: number }): Promise<{ keys: string[]; cursor?: string }>;
}

export interface Secrets {
  /**
   * Plugin-level secret named in permissions.secrets. Values are registered for
   * log redaction. Connection secrets belong in contribution config fields
   * marked `"x-secret": true` and arrive already resolved in `config`.
   */
  get(name: string): Promise<string>;
}

export interface HttpClient {
  /**
   * fetch semantics. Destinations must match permissions.network; in production
   * all egress (including raw sockets) is enforced outside the process as well.
   */
  fetch(input: string | URL, init?: RequestInit & { timeoutMs?: number; inv?: InvocationContext }): Promise<Response>;
}

// ─── 3. Invocation context (per call) ────────────────────────────────────────

export interface InvocationContext {
  readonly invocationId: string;
  /** Aborted on cancel, deadline, drain timeout or shutdown. Must be honored. */
  readonly signal: AbortSignal;
  /** Epoch milliseconds. */
  readonly deadline: number;
  readonly workspaceId: string;
  readonly principal: Principal;
  readonly locale: string;
  readonly timeZone: string;
  readonly trace: { readonly traceparent: string; readonly tracestate?: string };
  /** Logger pre-tagged with invocation, contribution and trace ids. */
  readonly log: Logger;
}

export interface Principal {
  readonly kind: "user" | "schedule" | "system";
  /** Opaque, stable within a workspace. */
  readonly id: string;
  /** The following require permissions.userIdentity. */
  readonly displayName?: string;
  readonly email?: string;
  readonly roles?: readonly string[];
}

// ─── 4. Contributions ────────────────────────────────────────────────────────

export interface ContributionRegistrar {
  dataSource(id: string, impl: DataSource): void;
  transform(id: string, impl: Transform): void;
  visualization(id: string, impl: VisualizationServer): void;
  exporter(id: string, impl: Exporter): void;
  command(id: string, impl: Command): void;
}

export interface ContributionBase {
  /**
   * Upgrade persisted config/params/options written under an older manifest
   * `configVersion`. Called lazily when a saved report is opened or run.
   * Absent and version mismatch: the report is flagged "needs migration".
   */
  migrateConfig?(value: JsonValue, fromConfigVersion: number): Promise<JsonValue>;
}

export interface ValidationIssue {
  /** JSON Pointer into the validated value. */
  path: string;
  message: string;
  severity: "error" | "warning";
}

// 4.1 Data source

export interface DatasetDescriptor {
  id: string;
  displayName: string;
  description?: string;
  tags?: string[];
}

export interface DataSource<C = JsonValue> extends ContributionBase {
  /** Required if manifest capabilities.testConnection. */
  testConnection?(config: C, inv: InvocationContext): Promise<{ ok: true } | { ok: false; message: string }>;
  listDatasets(config: C, inv: InvocationContext): Promise<DatasetDescriptor[]>;
  getSchema(config: C, datasetId: string, inv: InvocationContext): Promise<TableSchema>;
  query(config: C, request: QueryRequest, inv: InvocationContext): Promise<QueryResult>;
}

export interface QueryRequest {
  datasetId: string;
  /** Projection; absent = all columns. */
  columns?: string[];
  /** Sent only if capabilities.filterPushdown. */
  filter?: FilterExpr;
  /** Sent only if capabilities.orderByPushdown. */
  orderBy?: { column: string; direction: "asc" | "desc"; nulls?: "first" | "last" }[];
  /** Sent only if capabilities.limitPushdown. */
  limit?: number;
  /** Validated against parametersSchema. */
  parameters: Record<string, JsonValue>;
}

/** Open union: new operators may appear in minors. Unknown operator → report applied.filter = false. */
export type FilterExpr =
  | { op: "and" | "or"; args: FilterExpr[] }
  | { op: "not"; arg: FilterExpr }
  | { op: "eq" | "neq" | "lt" | "lte" | "gt" | "gte"; column: string; value: ScalarValue }
  | { op: "in"; column: string; values: ScalarValue[] }
  | { op: "isNull"; column: string }
  | { op: "like"; column: string; pattern: string };

export interface QueryResult {
  /** Which pushed-down parts were fully applied; the host applies the rest. */
  applied: { filter: boolean; orderBy: boolean; limit: boolean };
  schema: TableSchema;
  /** Batches must match `schema`. Backpressure is honored end to end. */
  batches: AsyncIterable<RecordBatch>;
}

// 4.2 Transform

export interface Transform<P = JsonValue> extends ContributionBase {
  validate?(params: P, inputs: TableSchema[], inv: InvocationContext): Promise<ValidationIssue[]>;
  outputSchema(inputs: TableSchema[], params: P, inv: InvocationContext): Promise<TableSchema>;
  apply(inputs: AsyncIterable<RecordBatch>[], params: P, inv: InvocationContext): AsyncIterable<RecordBatch>;
}

// 4.3 Visualization (server half; client half in namespace Client)

export interface VisualizationServer<O = JsonValue> extends ContributionBase {
  validate?(options: O, schema: TableSchema, inv: InvocationContext): Promise<ValidationIssue[]>;
  /** Server-side shaping (aggregate/sample) before data reaches the browser. Default: first maxRows rows. */
  prepare?(input: AsyncIterable<RecordBatch>, schema: TableSchema, options: O, inv: InvocationContext): AsyncIterable<RecordBatch>;
  /** Required if manifest staticRender. Used by PDF/email exports. */
  renderStatic?(
    input: AsyncIterable<RecordBatch>,
    schema: TableSchema,
    options: O,
    target: { format: "svg" | "png"; width: number; height: number; theme: Theme },
    inv: InvocationContext,
  ): AsyncIterable<Uint8Array>;
}

export interface Theme {
  mode: "light" | "dark";
  fontFamily: string;
  palette: { categorical: string[]; sequential: string[]; foreground: string; background: string };
}

// 4.4 Exporter

export interface Exporter<O = JsonValue> extends ContributionBase {
  export(report: ReportSnapshot, options: O, inv: InvocationContext): Promise<ExportResult>;
}

export interface ExportResult {
  /** Must equal manifest mediaType unless the manifest declares a wildcard subtype. */
  mediaType: string;
  fileName: string;
  body: AsyncIterable<Uint8Array>;
}

export interface ReportSnapshot {
  id: string;
  title: string;
  description?: string;
  parameters: Record<string, JsonValue>;
  /** ISO 8601. */
  generatedAt: string;
  sections: ReportSection[];
}

export interface ReportSection {
  id: string;
  title?: string;
  kind: "table" | "visualization" | "text";
  /** Markdown, for kind "text". */
  text?: string;
  schema?: TableSchema;
  /** Lazily streamed from the host. */
  rows?(): AsyncIterable<RecordBatch>;
  /** Host renders via the visualization's renderStatic; throws INCOMPATIBLE if unsupported. */
  renderImage?(target: { format: "svg" | "png"; width: number; height: number }): AsyncIterable<Uint8Array>;
}

// 4.5 Command

export interface Command<A = JsonValue> extends ContributionBase {
  run(args: A, inv: InvocationContext): Promise<{ message?: string; data?: JsonValue }>;
}

// ─── 5. Events (observer-only) ───────────────────────────────────────────────

/** Open union: new events may be added in minors. */
export interface HostEventPayloads {
  "report.run.started": { reportId: string; runId: string; trigger: "user" | "schedule" | "api" };
  "report.run.completed": { reportId: string; runId: string; durationMs: number; rowCount: number };
  "report.run.failed": { reportId: string; runId: string; errorCode: PluginErrorCode | string };
  "report.published": { reportId: string; version: number };
  "schedule.triggered": { scheduleId: string; reportId: string };
}

export interface Events {
  /** Event must be listed in contributes.eventSubscriptions. Delivery is at-least-once; handlers must be idempotent. */
  on<E extends keyof HostEventPayloads>(
    event: E,
    handler: (payload: HostEventPayloads[E], inv: InvocationContext) => Promise<void>,
  ): void;
}

// ─── 6. Inter-plugin services (host-mediated) ────────────────────────────────

export type ServiceHandler = {
  [method: string]: (args: JsonValue, inv: InvocationContext) => Promise<JsonValue>;
};

export interface ServiceClient {
  /** Negotiated provider service version. */
  readonly version: string;
  call<R extends JsonValue = JsonValue>(method: string, args: JsonValue, inv: InvocationContext): Promise<R>;
}

export interface Services {
  /** Name must be in exports.services. */
  provide(name: string, handler: ServiceHandler): void;
  /** Provider and service must be in dependencies. Survives provider reloads. Throws INCOMPATIBLE for an absent optional dependency. */
  consume(pluginId: string, name: string): ServiceClient;
}

// ─── 7. Errors ───────────────────────────────────────────────────────────────

/** Open union: treat unknown codes as INTERNAL. */
export type PluginErrorCode =
  | "INVALID_CONFIG"
  | "INVALID_ARGUMENT"
  | "NOT_FOUND"
  | "PERMISSION_DENIED"
  | "UPSTREAM_UNAUTHENTICATED"
  | "UPSTREAM_UNAVAILABLE"
  | "QUOTA_EXCEEDED"
  | "TIMEOUT"
  | "CANCELLED"
  | "OVERLOADED"
  | "PLUGIN_CRASHED"
  | "PLUGIN_UNAVAILABLE"
  | "INCOMPATIBLE"
  | "INTERNAL";

export declare class PluginError extends Error {
  constructor(
    code: PluginErrorCode,
    message: string,
    options?: { retryable?: boolean; userMessage?: string; details?: Record<string, JsonValue>; cause?: unknown },
  );
  readonly code: PluginErrorCode;
  readonly retryable: boolean;
  /** Safe to show to report viewers. `message` and `details` go to logs only. */
  readonly userMessage?: string;
  readonly details?: Record<string, JsonValue>;
}

// ─── 8. Browser-side visualization API (runs in sandboxed iframe) ────────────

export declare namespace Client {
  /** Default export of manifest visualizations[].clientEntry. */
  interface VisualizationModule<O = JsonValue> {
    mount(root: HTMLElement, props: RenderProps<O>, host: ClientHost): void | Promise<void>;
    update(props: RenderProps<O>): void | Promise<void>;
    unmount(): void;
  }

  interface RenderProps<O> {
    data: Table;
    options: O;
    size: { width: number; height: number };
    theme: Theme;
    locale: string;
    timeZone: string;
  }

  interface ClientHost {
    /** Cross-filter selection; column names and values only. */
    emitSelection(selection: { column: string; values: ScalarValue[] }[] | null): void;
    reportError(error: { message: string; code?: PluginErrorCode }): void;
  }
}

