| Templates | One working example repo per contribution type, CI preconfigured |
| Docs | Guides for each contribution type, a capabilities cookbook, and "how to pass approval" |

Minimal plugin:

```ts
import { definePlugin, PluginError } from "@reporting/plugin-sdk";

export default definePlugin({
  async activate(ctx) {
    ctx.contributions.registerDataSource("netsuite", {
      async testConnection(conn, inv) {
        const res = await ctx.http.fetch(`${conn.config.baseUrl}/ping`, { auth: { secret: "oauth" }, signal: inv.signal });
        return res.ok ? { ok: true } : { ok: false, message: `HTTP ${res.status}` };
      },
      async *query(req, inv) {
        let page = await fetchPage(ctx, req, undefined, inv);
        while (page) {
          yield page.batch;
          page = page.next ? await fetchPage(ctx, req, page.next, inv) : undefined;
        }
      },
    });
  },
});
