## 3. Manifest

### 3.1 Package format (`.rptplugin`, a gzip tarball)
```
manifest.json
dist/backend/index.js   # single self-contained ESM bundle; no runtime npm install
dist/ui/index.html      # optional
assets/
CHECKSUMS.sha256        # every file
SIGNATURE               # detached signature over CHECKSUMS
```

### 3.2 Example
```json
{
  "$schema": "https://schemas.rpt.internal/plugin-manifest/1.json",
  "manifestVersion": 1,
  "id": "acme.warehouse",
  "version": "2.1.0",
  "displayName": "Acme Warehouse Connector",
  "publisher": { "team": "data-platform", "contact": "data-platform@acme.internal" },
  "engines": { "hostApi": "^2.1.0" },
  "runtime": {
    "backend": { "entry": "dist/backend/index.js", "kind": "node" },
    "ui": { "entry": "dist/ui/index.html" }
  },
  "activation": ["onDataSource:postgres", "onCommand:refresh-catalog"],
  "contributes": {
    "dataSources": [{ "id": "postgres", "displayName": "Acme Postgres",
                      "configSchema": { "$ref": "#/definitions/pgConfig" },
                      "supportsPushdown": ["filter", "projection", "limit"] }],
    "commands": [{ "id": "refresh-catalog", "title": "Refresh catalog", "context": ["dataSource"] }]
  },
  "capabilities": [
    { "name": "net:fetch", "hosts": ["warehouse.acme.internal:5432"] },
    { "name": "secrets:read", "keys": ["pg-password"] },
    { "name": "storage:kv", "quotaMb": 10 }
  ],
  "dependencies": { "plugins": { "acme.auth-common": "^1.0.0" } },
