}

// ───── Exporter ─────
export interface ExporterProvider<O = Json> extends OptionsAware<O> {
  export(doc: ReportDocument, options: O, call: CallContext): AsyncIterable<Uint8Array>;
}
export interface ReportDocument {
  readonly title: string;
  readonly generatedAt: string;                         // ISO-8601
  readonly parameters: Readonly<Record<string, Scalar>>;
  readonly sections: readonly {
    readonly title?: string;
    readonly tiles: readonly Tile[];
  }[];
}
export type Tile =
  | { readonly kind: 'table'; readonly title?: string; readonly schema: ArrowSchema; readonly batches: AsyncIterable<RecordBatch> }
  | { readonly kind: 'image'; readonly title?: string; readonly mimeType: 'image/png' | 'image/svg+xml'; readonly bytes: Uint8Array }
  | { readonly kind: 'text'; readonly markdown: string }
  | { readonly kind: 'unavailable'; readonly title?: string; readonly reason: string }
  | { readonly kind: string & {} };                     // open union: ignore unknown kinds

// ───── Action ─────
export interface ActionProvider<O = Json> extends OptionsAware<O> {
  run(input: ActionInput<O>, call: CallContext): Promise<ActionResult>;
}
export interface ActionInput<O> {
  readonly options: O;
  readonly idempotencyKey: string;
  readonly trigger: 'reportToolbar' | 'tileMenu' | 'rowContext' | 'schedule' | (string & {});
  readonly report: { readonly id: string; readonly parameters: Readonly<Record<string, Scalar>> };
  readonly selection?: { readonly schema: ArrowSchema; readonly rows: RecordBatch };  // requires reportData: 'read'
}
export type ActionResult =
  | { readonly status: 'ok'; readonly message?: string; readonly link?: string }
  | { readonly status: 'error'; readonly message: string };

// ───── Capabilities ─────
export interface Secrets { get(name: string): Promise<string> }          // PERMISSION_DENIED if undeclared
export interface KeyValueStore {
  get(key: string): Promise<Json | undefined>;
  set(key: string, value: Json, opts?: { ttlSec?: number }): Promise<void>;
  delete(key: string): Promise<void>;
  list(prefix: string, opts?: { limit?: number; cursor?: string }): Promise<{ keys: string[]; cursor?: string }>;
}
export interface Logger {
  debug(msg: string, fields?: Json): void; info(msg: string, fields?: Json): void;
  warn(msg: string, fields?: Json): void;  error(msg: string, fields?: Json): void;
}
export interface Metrics {
  counter(name: string, labels?: Record<string, string>): { inc(n?: number): void };
  histogram(name: string, labels?: Record<string, string>): { observe(v: number): void };
}

// ───── Errors ─────
export class PluginError extends Error {
  constructor(code: PluginErrorCode, message: string,
              opts?: { retryable?: boolean; userMessage?: string; cause?: unknown });
  readonly code: PluginErrorCode;
  readonly retryable: boolean;
  readonly userMessage?: string;       // the ONLY text ever shown to end users
}
export type PluginErrorCode =
  | 'INVALID_OPTIONS' | 'AUTH_FAILED' | 'NOT_FOUND' | 'UPSTREAM_UNAVAILABLE'
  | 'UPSTREAM_TIMEOUT' | 'QUOTA_EXCEEDED' | 'CANCELLED' | 'INTERNAL';
// Host-generated (plugins observe, never throw): PLUGIN_UNAVAILABLE, PLUGIN_CRASHED, PLUGIN_RELOADING,
// CALL_TIMEOUT, PERMISSION_DENIED, INCOMPATIBLE_API, PAYLOAD_TOO_LARGE, INTEGRITY
// Any non-PluginError throw → INTERNAL; message logged, never shown to users (may contain sensitive data).

export type ApiFeature = 'dataSource.incremental' | 'dataSource.aggregatePushdown' | (string & {});
export type Json = null | boolean | number | string | Json[] | { [k: string]: Json };
export type Scalar = null | boolean | number | string | { readonly $date: string } | { readonly $decimal: string };
