interface VizHost {
  readonly apiVersion: string; supports(feature: string): boolean;
  emit(event: { type: "select" | "drill" | string; payload: unknown }): void;
  reportError(err: { userMessage: string; detail?: string }): void;
}
interface VizInstance {
  update(input: { data: RecordBatch[]; bindings: Record<string, string[]>; options: unknown;
                  theme: Theme; locale: string; timeZone: string }): void | Promise<void>;
  resize(size: { width: number; height: number }): void;
  destroy(): void;
}
