  "unevaluatedProperties": false,
  "required": ["manifestVersion", "id", "version", "displayName", "publisher",
               "apiVersion", "engines", "main", "contributes"],
  "properties": {
    "manifestVersion": { "const": 1 },
    "id": { "type": "string", "pattern": "^[a-z][a-z0-9-]{1,38}\\.[a-z][a-z0-9-]{1,63}$" },
    "version": { "$ref": "#/$defs/semver" },
