## 6. API contract (v1.0 surface)

Published as `@reporting/plugin-sdk` (the runtime shim plus helpers) and `@reporting/plugin-api` (types only, generated from the IDL, §7.2).

### 6.1 Context

```ts
export interface PluginContext {
  readonly plugin: { id: string; version: string; generation: number; installationId: string };
  readonly api: { version: string; supports(feature: FeatureFlag): boolean };
  readonly subscriptions: DisposableStore;

  readonly register: Registrar;
  readonly config: ConfigService;
  readonly storage: StorageService;
  readonly secrets: SecretService;
  readonly http: HttpService;
  readonly data: DataService;
  readonly events: EventService;
  readonly services: ServiceClient;
  readonly timers: TimerService;
  readonly log: Logger;
  readonly metrics: Metrics;
}

export interface Registrar {
  datasource(id: string, impl: DataSourceProvider): Disposable;
  transform(id: string, impl: TransformProvider): Disposable;
  visualization(id: string, impl: VisualizationServer): Disposable;   // prepare + migrateOptions
  exporter(id: string, impl: ExporterProvider): Disposable;
  action(id: string, impl: ActionProvider): Disposable;
  service(id: string, impl: ServiceProvider): Disposable;
}
```

### 6.2 Invocation context (passed to every contribution call)

```ts
export interface InvocationContext {
  readonly invocationId: string;
  readonly idempotencyKey: string;      // stable across host retries of the same logical call
  readonly attempt: number;             // 1-based
  readonly principal: Principal;        // user or service identity, tenant/workspace
  readonly deadline: number;            // epoch ms
  readonly signal: AbortSignal;         // fires on cancel or deadline
  readonly locale: string;
  readonly timeZone: string;
  readonly trace: { traceparent: string };
  readonly log: Logger;                 // pre-tagged with invocationId, traceId
}

export interface Principal {
  kind: "user" | "service" | (string & {});
  id: string;
  workspaceId: string;
  displayName?: string;
}
```

### 6.3 Host services

```ts
export interface ConfigService {
  get<T = unknown>(): T;                                   // validated against settings schema
}

export interface StorageService {                           // namespace: installation × workspace
  get<T extends JsonValue>(key: string): Promise<T | undefined>;
  set(key: string, value: JsonValue, opts?: { ttlSeconds?: number; ifVersion?: number }): Promise<{ version: number }>;
  delete(key: string): Promise<void>;
  list(prefix: string, opts?: { cursor?: string; limit?: number }): Promise<{ keys: string[]; cursor?: string }>;
  readonly schemaVersion: number;
}                                                           // keys ≤ 512 bytes, values ≤ 1 MiB, quota per manifest

export interface SecretService {
  read(name: string, inv: InvocationContext): Promise<string>;   // requires permissions.secrets.read; audited
}

export interface HttpService {
  fetch(url: string, init: HttpRequestInit, inv: InvocationContext): Promise<HttpResponse>;
}
export interface HttpRequestInit {
  method?: string;
  headers?: Record<string, string>;
  body?: Uint8Array | string;
  auth?: { secret: string; scheme: "bearer" | "basic" | "header"; headerName?: string };  // injected host-side
  timeoutMs?: number;                                       // capped by invocation deadline
  maxResponseBytes?: number;                                // capped by host policy (default 50 MiB)
}

export interface DataService {                              // executes as inv.principal
  query(req: HostQuery, inv: InvocationContext): AsyncIterable<RecordBatch>;
}

export interface EventService {
  subscribe(topic: string, handler: (e: HostEvent, inv: InvocationContext) => Promise<void>): Disposable;
  publish(topic: `plugin.${string}`, payload: JsonValue, inv: InvocationContext): Promise<void>;
}

export interface ServiceClient {
  get(fqid: string): { call<R = JsonValue>(method: string, args: JsonValue, inv: InvocationContext): Promise<R> };
}
```
Passing `inv` into every service call ties I/O to a principal, deadline, trace, and audit record. This is required, not a convenience.

### 6.4 Datasource

```ts
export interface DataSourceProvider {
  testConnection(conn: ConnectionRef, inv: InvocationContext): Promise<TestResult>;
  listDatasets(conn: ConnectionRef, inv: InvocationContext): Promise<DatasetInfo[]>;
  getSchema(conn: ConnectionRef, dataset: string, inv: InvocationContext): Promise<Schema>;
  query(req: DataSourceQuery, inv: InvocationContext): AsyncIterable<RecordBatch>;
}

export interface DataSourceQuery {
  connection: ConnectionRef;                 // config + secret *names*, never values
  dataset: string;
  columns: string[];
  filters?: FilterExpr;                      // only if capabilities.filterPushdown
  aggregations?: AggregationSpec;            // only if capabilities.aggregationPushdown
  since?: IncrementalCursor;                 // only if capabilities.incremental
  limit?: number;
  options: unknown;                          // validated against optionsSchema
}
export interface TestResult { ok: boolean; message?: string; details?: JsonValue }
```
If a plugin gets filters it can't push down, it returns `INVALID_ARGUMENT`. The host never sends filters unless the manifest declares the capability, and it applies residual filters itself.

