## 6. API contract (v1.0)

Published as two packages:
- `@reporting/plugin-api`: types, generated from the IDL.
- `@reporting/plugin-sdk`: the shim plus helpers.

### 6.1 Context and invocation
```ts
export interface PluginContext {
  readonly plugin: { id: string; version: string; generation: number; installationId: string };
  readonly api: { version: string; supports(feature: FeatureFlag): boolean };
  readonly subscriptions: DisposableStore;
  readonly register: Registrar;
  readonly config: ConfigService;   readonly storage: StorageService;
  readonly secrets: SecretService;  readonly http: HttpService;
  readonly data: DataService;       readonly events: EventService;
  readonly services: ServiceClient; readonly timers: TimerService;
  readonly log: Logger;             readonly metrics: Metrics;
}
export interface Registrar {
  datasource(id: string, impl: DataSourceProvider): Disposable;
  transform(id: string, impl: TransformProvider): Disposable;
  visualization(id: string, impl: VisualizationServer): Disposable;
  exporter(id: string, impl: ExporterProvider): Disposable;
  action(id: string, impl: ActionProvider): Disposable;
  service(id: string, impl: ServiceProvider): Disposable;
}
export interface InvocationContext {
  readonly invocationId: string;
  readonly idempotencyKey: string;   // stable across host retries
  readonly attempt: number;
  readonly principal: { kind: "user" | "service" | (string & {}); id: string; workspaceId: string };
  readonly deadline: number;
  readonly signal: AbortSignal;
  readonly locale: string; readonly timeZone: string;
  readonly trace: { traceparent: string };
  readonly log: Logger;
}
```

### 6.2 Host services
Every I/O call takes `inv`. That ties the call to a principal, a deadline, a trace and an audit record, and it is required.
```ts
interface ConfigService { get<T = unknown>(): T }
interface StorageService {                       // keys ≤512B, values ≤1MiB, quota from manifest
  get<T extends JsonValue>(key: string): Promise<T | undefined>;
  set(key: string, value: JsonValue, o?: { ttlSeconds?: number; ifVersion?: number }): Promise<{ version: number }>;
  delete(key: string): Promise<void>;
  list(prefix: string, o?: { cursor?: string; limit?: number }): Promise<{ keys: string[]; cursor?: string }>;
  readonly schemaVersion: number;
}
interface SecretService { read(name: string, inv: InvocationContext): Promise<string> }   // secrets.read only
interface HttpService {
  fetch(url: string, init: {
    method?: string; headers?: Record<string, string>; body?: Uint8Array | string;
    auth?: { secret: string; scheme: "bearer" | "basic" | "header"; headerName?: string };  // injected host-side
    timeoutMs?: number; maxResponseBytes?: number;
  }, inv: InvocationContext): Promise<HttpResponse>;
}
interface DataService { query(req: HostQuery, inv: InvocationContext): AsyncIterable<RecordBatch> }
interface EventService {
  subscribe(topic: string, h: (e: HostEvent, inv: InvocationContext) => Promise<void>): Disposable;
  publish(topic: `plugin.${string}`, payload: JsonValue, inv: InvocationContext): Promise<void>;
}
interface ServiceClient { get(fqid: string): { call<R>(method: string, args: JsonValue, inv: InvocationContext): Promise<R> } }
```

### 6.3 Contribution interfaces
```ts
export interface DataSourceProvider {
  testConnection(conn: ConnectionRef, inv: InvocationContext): Promise<{ ok: boolean; message?: string }>;
  listDatasets(conn: ConnectionRef, inv: InvocationContext): Promise<DatasetInfo[]>;
  getSchema(conn: ConnectionRef, dataset: string, inv: InvocationContext): Promise<Schema>;
  query(req: {
    connection: ConnectionRef;          // config + secret *names*
    dataset: string; columns: string[];
    filters?: FilterExpr;               // only sent if filterPushdown; host applies residuals
    aggregations?: AggregationSpec;     // only if aggregationPushdown
    since?: IncrementalCursor;          // only if incremental
    limit?: number; options: unknown;
  }, inv: InvocationContext): AsyncIterable<RecordBatch>;
}

export interface TransformProvider {
  outputSchema(input: Schema, options: unknown): Schema | Promise<Schema>;   // pure, no I/O
  run(input: AsyncIterable<RecordBatch>, options: unknown, inv: InvocationContext): AsyncIterable<RecordBatch>;
  migrateOptions?(options: unknown, fromVersion: number): unknown;
}

export interface VisualizationServer {
  prepare?(data: AsyncIterable<RecordBatch>, options: unknown, inv: InvocationContext): Promise<JsonValue | RecordBatch[]>;
  migrateOptions?(options: unknown, fromVersion: number): unknown;
}
export interface VisualizationClient {                     // browser bundle, in iframe
  mount(host: VizHost): void | Promise<void>;
  render(input: {
    contributionId: string; data: RecordBatch[] | JsonValue; roles: Record<string, string[]>;
    options: unknown; theme: ThemeTokens; size: { width: number; height: number };
    locale: string; timeZone: string; mode: "interactive" | "static";
  }): void | Promise<void>;
  resize?(size: { width: number; height: number }): void;
  destroy?(): void;
}
export interface VizHost { readonly root: HTMLElement; rendered(): void; emit(e: VizEvent): void; log: Logger }
// bundle: export default defineVisualizations({ "pipeline-funnel": FunnelClient })

export interface ExporterProvider {                        // idempotent on inv.idempotencyKey
  export(req: { format: string; report: RenderedReportRef; target: unknown }, inv: InvocationContext)
    : Promise<{ artifactRef?: string; externalUrl?: string; details?: JsonValue }>;
}
export interface ActionProvider { handle(e: HostEvent, inv: InvocationContext): Promise<void> }   // at-least-once
```

### 6.4 Saved report compatibility
Report blocks store `{fqid, optionsSchemaVersion, options}`.

| Case | What happens |
|---|---|
| Stored version older | The host calls `migrateOptions` (pure, chained) in the sandbox, validates the result against the current schema, and writes it back only when the user saves. |
| Stored version newer (after a rollback) | The block shows "requires plugin ≥ X", and the stored options are never overwritten. |
| Migration fails | Error placeholder; the original options are kept. |

### 6.5 Errors
```ts
export class PluginError extends Error {
  constructor(public code: ErrorCode, message: string,
              public opts: { retryable?: boolean; details?: JsonValue; cause?: unknown } = {}) { super(message) }
}
export type ErrorCode = "INVALID_ARGUMENT" | "UNAUTHENTICATED" | "PERMISSION_DENIED" | "NOT_FOUND"
  | "CONFLICT" | "RATE_LIMITED" | "QUOTA_EXCEEDED" | "UNAVAILABLE" | "TIMEOUT" | "CANCELLED"
  | "UNSUPPORTED" | "INTERNAL" | (string & {});
```
- Any error that isn't a `PluginError` becomes `INTERNAL`. Only the message crosses the boundary, capped at 4KiB, and stacks go to logs.
- The host retries only `retryable` errors, plus `UNAVAILABLE`/`TIMEOUT` on idempotent kinds. It retries at most twice, within the deadline.
- `RATE_LIMITED` may include `details.retryAfterMs`.

### 6.6 Behavioural contract (covered by the TCK)
| Topic | Contract |
|---|---|
| Cancellation | Stop within 2s of `inv.signal` aborting |
| Idempotency | Exporters and actions are at-least-once and must dedupe on `idempotencyKey` |
| Streaming | Batches ≤64MiB and ≤100k rows; credit-based backpressure (the SDK iterator waits for credit) |
| Schema fidelity | First batch validated fully, later ones sampled; a mismatch is a plugin fault |
| Concurrency | Up to `maxConcurrency` concurrent calls per instance |
| Open enums | `(string & {})` unions can grow in minor releases, so handle unknown values |
| Purity | `outputSchema` and `migrateOptions` must be pure; `deterministic` transforms can be cached |

