```ts
// src/server.ts
import { definePlugin, PluginError } from "@reporting/plugin-sdk";

export default definePlugin({
  async activate(ctx) {
    ctx.register.datasource("opportunities", {
      async testConnection(conn, inv) {
        const r = await ctx.http.fetch(`${conn.config.instanceUrl}/services/data`,
          { auth: { secret: conn.secrets.oauth, scheme: "bearer" } }, inv);
        return { ok: r.status === 200, message: r.status === 200 ? undefined : `HTTP ${r.status}` };
      },
      async listDatasets() { return [{ name: "opportunities", displayName: "Opportunities" }]; },
      async getSchema() { return OPPORTUNITY_SCHEMA; },
      async *query(req, inv) {
        for await (const page of paginate(ctx, req, inv)) {
          if (inv.signal.aborted) throw new PluginError("CANCELLED", "cancelled");
          yield toRecordBatch(page, OPPORTUNITY_SCHEMA);
        }
      }
    });
  },
  async migrateStorage({ from, storage }) { if (from < 2) { /* rewrite cursor keys */ } }
});
```

**Package layout:** `plugin.json`, `schemas/`, `dist/server.js` (bundled, no native addons), `dist/client.js` (ESM), `assets/`, `CHANGELOG.md`. `rpt-plugin pack` produces `<id>-<version>.rptp`, a zip with `SHA256SUMS` and `signature`.

