## 7. Plugin API 1.0 (TypeScript SDK surface)

Source of truth: JSON Schemas in the `plugin-api` repo (§9). The SDKs are generated from them, and
this section mirrors them.

### 7.1 Entry point and context

```ts
import { definePlugin } from "@reporting/plugin-sdk";

export default definePlugin({
  async onLoad(ctx) {
    ctx.contributions.datasource("salesforce", new SalesforceSource(ctx));
  },
  async onUnload(event) { /* best-effort */ },
});
```

```ts
export interface Plugin {
  onLoad(ctx: PluginContext): Promise<void>;
  onUnload?(event: UnloadEvent): Promise<void>;
  onConfigChange?(event: ConfigChangeEvent): Promise<"applied" | "reload">;
  healthCheck?(): Promise<HealthReport>;
}

export interface PluginContext {
  readonly plugin: { id: string; version: string; apiVersion: string };
  readonly instance: {
    id: string;
    isolationKey: string;                 // tenant id or "shared"
    loadReason: "startup" | "activation" | "reload" | "upgrade" | "crash-restart" | "config-change";
    previousVersion: string | null;       // set on upgrade/rollback
  };
  readonly host: { version: string; apiVersion: string; supports(feature: string): boolean };
  readonly config: Readonly<Record<string, unknown>>;
  readonly contributions: ContributionRegistrar;
  readonly log: Logger;
  readonly metrics: Metrics;
  readonly secrets: Secrets;
  readonly storage: KeyValueStore;
  readonly http: HttpClient;
  readonly scratch: { path: string; quotaBytes: number };
  readonly signal: AbortSignal;           // aborted when the instance starts unloading
}

export interface UnloadEvent {
  reason: "disable" | "uninstall" | "reload" | "upgrade" | "rollback" | "idle" | "shutdown" | "recycle";
  deadline: number;                       // epoch ms
}
export interface ConfigChangeEvent { previous: Readonly<Record<string, unknown>>; next: Readonly<Record<string, unknown>> }
export interface HealthReport { status: "healthy" | "degraded" | "unhealthy"; detail?: string }

export interface ContributionRegistrar {
  datasource(id: string, impl: DataSource): void;
  transform(id: string, impl: Transform): void;
  visualization(id: string, impl: Visualization): void;
  exporter(id: string, impl: Exporter): void;
  delivery(id: string, impl: Delivery): void;
  function(id: string, impl: ScalarFunction): void;
}
```

### 7.2 Call context

```ts
export interface CallContext {
  readonly callId: string;
  readonly signal: AbortSignal;
  readonly deadline: number;                    // epoch ms
  readonly invoker: { userId: string; tenantId: string; locale: string; timeZone: string };
  readonly runId: string | null;                // null for interactive/editor calls
  readonly idempotencyKey: string;              // stable across host retries of the same logical call
  readonly traceparent: string;                 // W3C trace context
  readonly datasets: { read(ref: DatasetRef, opts?: ReadOptions): RecordBatchStream };   // requires datasets.read
  readonly reports: { metadata(ref: ReportRef): Promise<ReportMetadata> };               // requires reports.metadata.read
  readonly notifications: { send(n: Notification): Promise<void> };                      // requires notifications.send
}
```

### 7.3 Contribution interfaces

Every contribution can also implement `migrateConfig?(fromVersion: number, config: unknown): Promise<unknown>`.

```ts
// ── Data ─────────────────────────────────────────────────────────────
export type RecordBatchStream = AsyncIterable<RecordBatch>;   // Apache Arrow record batches
export interface Schema { fields: Field[] }
export interface Field { name: string; type: ValueType; nullable: boolean; metadata?: Record<string, string> }

// ── Datasource ───────────────────────────────────────────────────────
export interface DataSource {
  testConnection(conn: unknown, call: CallContext): Promise<{ ok: true } | { ok: false; message: string }>;
  discoverSchema(conn: unknown, req: { path?: string[]; cursor?: string }, call: CallContext): Promise<SchemaCatalog>;
  planQuery?(conn: unknown, query: QuerySpec, call: CallContext): Promise<QueryPlan>;
  query(conn: unknown, query: QuerySpec, call: CallContext): RecordBatchStream;
}
export interface QuerySpec {
  entity: string[];                          // e.g. ["Opportunity"]
  columns: string[];
  filter?: FilterExpr;                        // only if "filter" in manifest pushdown
  sort?: { column: string; direction: "asc" | "desc" }[];
  limit?: number;
  aggregate?: { groupBy: string[]; measures: { column: string; fn: "sum" | "count" | "min" | "max" | "avg" }[] };
  parameters: Record<string, unknown>;
}
export interface QueryPlan { accepted: ("project" | "filter" | "sort" | "limit" | "aggregate")[]; outputSchema: Schema }
// The host applies whatever pushdown the plan did not accept. If planQuery is absent, the manifest's pushdown list applies.

// ── Transform ────────────────────────────────────────────────────────
export interface Transform {
  outputSchema(inputs: Schema[], params: unknown, call: CallContext): Promise<Schema>;
  execute(inputs: RecordBatchStream[], params: unknown, call: CallContext): RecordBatchStream;
}

// ── Visualization ────────────────────────────────────────────────────
export interface Visualization {
  validateOptions?(options: unknown, dataSchema: Schema, call: CallContext): Promise<ValidationIssue[]>;
  render(data: Dataset, options: unknown, env: RenderEnv, call: CallContext): Promise<VizSpec>;
}
export interface RenderEnv { width: number; height: number; theme: "light" | "dark"; target: "screen" | "print" }

// ── Exporter ─────────────────────────────────────────────────────────
export interface Exporter {
  export(report: RenderedReport, options: unknown, call: CallContext): AsyncIterable<Uint8Array>;
}

// ── Delivery ─────────────────────────────────────────────────────────
export interface Delivery {
  validateTarget(target: unknown, call: CallContext): Promise<ValidationIssue[]>;
  deliver(artifacts: ArtifactHandle[], target: unknown, call: CallContext): Promise<{ externalId?: string }>;
  // MUST dedupe on call.idempotencyKey: the host retries retryable failures.
}

// ── Scalar function ──────────────────────────────────────────────────
export interface ScalarFunction {
  evaluate(args: ColumnVector[], call: CallContext): Promise<ColumnVector>;   // vectorized; one row per input row
}
```

### 7.4 Errors

```ts
export class PluginError extends Error {
  constructor(
    readonly code: ErrorCode,
    message: string,
    readonly opts?: { retryable?: boolean; userMessage?: string; details?: Record<string, unknown> }
  ) { super(message); }
}
```

| Code | Raised by | Retryable default | Meaning |
|---|---|---|---|
| `INVALID_ARGUMENT` | plugin / host | no | The input is bad even though it passed schema validation. |
| `NOT_FOUND` | plugin / host | no | The entity, dataset, or artifact does not exist. |
| `PERMISSION_DENIED` | plugin / host | no | The upstream system or a grant refused access. |
| `CAPABILITY_NOT_DECLARED` | host | no | The plugin called an API it did not declare. This is a bug in the plugin. |
| `UNAUTHENTICATED` | plugin | no | Upstream credentials are invalid or expired. |
| `UPSTREAM_ERROR` | plugin | yes | An external system failed. |
| `RATE_LIMITED` | plugin / host | yes | Set `details.retryAfterMs`. |
| `RESOURCE_EXHAUSTED` | host | no | A quota, memory, or message-size limit was hit. |
| `TIMEOUT` | host | yes | The call deadline passed. |
| `CANCELLED` | host | no | The caller cancelled. |
| `PLUGIN_CRASHED` | host | yes (once) | The instance died during the call. |
| `PLUGIN_RELOADED` | host | yes | The drain timeout expired during a reload. |
| `UNAVAILABLE` | host | yes | No active instance, or the plugin is quarantined or disabled. |
| `NOT_IMPLEMENTED` | plugin / host | no | An optional method is missing. |
| `INTERNAL` | plugin / host | no | Any unexpected exception. The SDK maps uncaught exceptions to this. |

`userMessage` is shown to report users. `message` and `details` go only to logs. **Codes are an open
set:** when a caller receives an unknown code, it treats it as `INTERNAL` and uses the `retryable`
flag as sent.

### 7.5 Visualization spec formats

```ts
export type VizSpec =
  | { format: "vega-lite"; version: "5"; spec: object }       // host strips/rejects: data.url, external images, signals with expr callbacks
  | { format: "table"; version: "1"; columns: TableColumn[]; rows: "inline" | "bound" }
  | { format: "iframe"; version: "1"; props: object };      // only if manifest renderer = "iframe"
```

The host advertises the formats it supports in `features`, for example `viz.vega-lite@5`. Plugins
check with `ctx.host.supports(...)`.

