```proto
syntax = "proto3";

package reporting.plugin.v1;

import "google/protobuf/duration.proto";
import "google/protobuf/struct.proto";
import "google/protobuf/timestamp.proto";

// Stability: stable

// Sent with every contribution invocation. Plugins MUST send capability_token
// (metadata x-rpt-capability) on host-service calls made for this invocation;
// the SDKs do this automatically.
message InvocationContext {
  string invocation_id = 1;
  string tenant_id = 2;
  Principal principal = 3;
  string capability_token = 4;
  google.protobuf.Timestamp deadline = 5;
  string traceparent = 6;                  // W3C trace context
  string locale = 7;                       // BCP 47
  string time_zone = 8;                    // IANA
  ContributionRef contribution = 9;
  google.protobuf.Struct config = 10;      // validated against configSchema by the host
  uint32 config_schema_version = 11;       // always the current version; host migrates first
}

message ContributionRef {
  ContributionKind kind = 1;
  string id = 2;
}

enum ContributionKind {
  CONTRIBUTION_KIND_UNSPECIFIED = 0;
  CONTRIBUTION_KIND_DATA_SOURCE = 1;
  CONTRIBUTION_KIND_TRANSFORM = 2;
  CONTRIBUTION_KIND_VISUALIZATION = 3;
  CONTRIBUTION_KIND_EXPORTER = 4;
  CONTRIBUTION_KIND_ACTION = 5;
}

message Principal {
  enum Kind {
    KIND_UNSPECIFIED = 0;
    KIND_USER = 1;
    KIND_SCHEDULE = 2;   // runs as the schedule owner
    KIND_SYSTEM = 3;     // lifecycle only; cannot read datasets
  }
  Kind kind = 1;
  string id = 2;
  string display_name = 3;
}

// Attached as a gRPC status detail on every failed RPC.
message PluginError {
  ErrorCode code = 1;
  string reason = 2;         // stable, plugin-defined, e.g. "LEDGER_PERIOD_CLOSED"
  string user_message = 3;   // safe for end users, localized
  string debug_detail = 4;   // operators only; MUST NOT contain secrets
  bool retryable = 5;
  google.protobuf.Duration retry_after = 6;
  map<string, string> metadata = 7;
}

enum ErrorCode {
  ERROR_CODE_UNSPECIFIED = 0;
  ERROR_CODE_INVALID_ARGUMENT = 1;
  ERROR_CODE_INVALID_CONFIG = 2;
  ERROR_CODE_UPSTREAM_AUTH_FAILED = 3;
  ERROR_CODE_PERMISSION_DENIED = 4;
  ERROR_CODE_NOT_FOUND = 5;
  ERROR_CODE_CONFLICT = 6;
  ERROR_CODE_RESOURCE_EXHAUSTED = 7;
  ERROR_CODE_UPSTREAM_UNAVAILABLE = 8;
  ERROR_CODE_DEADLINE_EXCEEDED = 9;
  ERROR_CODE_CANCELLED = 10;
  ERROR_CODE_UNSUPPORTED = 11;
  ERROR_CODE_DATA_ERROR = 12;
  ERROR_CODE_INTERNAL = 13;
}

// Arrow IPC stream-format schema message.
message ArrowSchema {
  bytes ipc_schema = 1;
}

// Arrow IPC record batch message; MUST match the schema announced in the stream header.
message ArrowRecordBatch {
  bytes ipc_batch = 1;
  uint64 row_count = 2;
}

message Progress {
  optional double fraction = 1;   // [0,1]; unset when unknown
  string message = 2;
  uint64 rows_processed = 3;
}

message ColumnMetadata {
  string name = 1;
  string display_name = 2;
  string description = 3;
  ColumnRole role = 4;
  string unit = 5;                // e.g. "USD", "ms"
  string format = 6;              // host format pattern hint
  bool filterable = 7;
  bool sortable = 8;
}

enum ColumnRole {
  COLUMN_ROLE_UNSPECIFIED = 0;
  COLUMN_ROLE_DIMENSION = 1;
  COLUMN_ROLE_MEASURE = 2;
  COLUMN_ROLE_TIME = 3;
  COLUMN_ROLE_GEO = 4;
  COLUMN_ROLE_IDENTIFIER = 5;
}
```

