```proto
syntax = "proto3";

package reporting.plugin.v1;

import "google/protobuf/timestamp.proto";

// Stability: stable

message QuerySpec {
  string entity = 1;
  repeated string columns = 2;             // empty = all
  Expression filter = 3;                   // unset = no filter
  repeated SortKey sort = 4;
  optional uint64 limit = 5;
  repeated string group_by = 6;
  repeated Aggregation aggregations = 7;
  IncrementalCursor cursor = 8;
  map<string, Literal> parameters = 9;     // report parameters
}

message SortKey {
  string column = 1;
  bool descending = 2;
  NullOrder nulls = 3;
}

enum NullOrder {
  NULL_ORDER_UNSPECIFIED = 0;
  NULL_ORDER_FIRST = 1;
  NULL_ORDER_LAST = 2;
}

message Aggregation {
  string output_name = 1;
  AggregateFunction function = 2;
  string column = 3;                       // empty for COUNT(*)
}

enum AggregateFunction {
  AGGREGATE_FUNCTION_UNSPECIFIED = 0;
  AGGREGATE_FUNCTION_COUNT = 1;
  AGGREGATE_FUNCTION_COUNT_DISTINCT = 2;
  AGGREGATE_FUNCTION_SUM = 3;
  AGGREGATE_FUNCTION_AVG = 4;
  AGGREGATE_FUNCTION_MIN = 5;
  AGGREGATE_FUNCTION_MAX = 6;
}

message IncrementalCursor {
  bytes token = 1;                         // opaque to the host
}

message Expression {
  oneof kind {
    ExpressionList all_of = 1;
    ExpressionList any_of = 2;
    Expression negate = 3;
    Comparison comparison = 4;
    InList in_list = 5;
    IsNull is_null = 6;
  }
}

message ExpressionList {
  repeated Expression expressions = 1;
}

message Comparison {
  string column = 1;
  ComparisonOperator operator = 2;
  Literal value = 3;
}

enum ComparisonOperator {
  COMPARISON_OPERATOR_UNSPECIFIED = 0;
  COMPARISON_OPERATOR_EQ = 1;
  COMPARISON_OPERATOR_NE = 2;
  COMPARISON_OPERATOR_LT = 3;
  COMPARISON_OPERATOR_LTE = 4;
  COMPARISON_OPERATOR_GT = 5;
  COMPARISON_OPERATOR_GTE = 6;
  COMPARISON_OPERATOR_CONTAINS = 7;
  COMPARISON_OPERATOR_STARTS_WITH = 8;
}

message InList {
  string column = 1;
  repeated Literal values = 2;
  bool negated = 3;
}

message IsNull {
  string column = 1;
  bool negated = 2;
}

// Typed literal; avoids the int64/decimal/timestamp loss of google.protobuf.Value.
message Literal {
  oneof value {
    bool bool_value = 1;
    int64 int_value = 2;
    double double_value = 3;
    string string_value = 4;
    string decimal_value = 5;              // canonical decimal string
    google.protobuf.Timestamp timestamp_value = 6;
    string date_value = 7;                 // YYYY-MM-DD
    bytes bytes_value = 8;
  }
}

// Stream contract for query results: exactly one header first, then zero or
// more batch/progress messages, then exactly one trailer last.
message QueryHeader {
  ArrowSchema schema = 1;
  repeated ColumnMetadata columns = 2;
  PushdownApplied applied = 3;
}

// Anything not applied is applied by the host. If aggregation is not applied,
// the plugin MUST return the un-aggregated columns referenced by group_by and aggregations.
message PushdownApplied {
  bool filter_fully_applied = 1;
  Expression residual_filter = 2;          // set when partially applied; unset + !fully_applied = host applies all
  bool sort_applied = 3;
  bool limit_applied = 4;
  bool aggregation_applied = 5;
}

message QueryTrailer {
  uint64 total_rows = 1;
  IncrementalCursor next_cursor = 2;
  bool truncated = 3;
  repeated string warnings = 4;
}
```

