```proto
syntax = "proto3";

package reporting.plugin.v1;

import "google/protobuf/struct.proto";
import "google/protobuf/timestamp.proto";
import "reporting/plugin/v1/common.proto";

// Stability: stable
// Implemented by every server-side plugin (the SDK provides it).
service PluginLifecycle {
  rpc Handshake(HandshakeRequest) returns (HandshakeResponse);
  // Called exactly once per instance.
  rpc Load(LoadRequest) returns (LoadResponse);
  // Only when settings.hotApply is true. Apply atomically.
  rpc Configure(ConfigureRequest) returns (ConfigureResponse);
  // Pure function, no I/O. Required if any configSchemaVersion > 1.
  rpc MigrateConfig(MigrateConfigRequest) returns (MigrateConfigResponse);
  // Old instance of a stateful reload. MUST keep serving afterwards.
  rpc PrepareReload(PrepareReloadRequest) returns (PrepareReloadResponse);
  // At most once; may never be called (crash, OOM, revoke).
  rpc Unload(UnloadRequest) returns (UnloadResponse);
  // Cheap, local; MUST NOT call upstream systems.
  rpc CheckHealth(CheckHealthRequest) returns (CheckHealthResponse);
}

message ApiVersion {
  uint32 major = 1;
  uint32 minor = 2;
}

message HandshakeRequest {
  string host_version = 1;
  repeated ApiVersion supported_api_versions = 2;
  repeated string host_features = 3;
  string instance_id = 4;
}

message HandshakeResponse {
  ApiVersion selected_api_version = 1;
  string plugin_id = 2;
  string plugin_version = 3;
  string sdk_name = 4;
  string sdk_version = 5;
  // MUST equal the manifest's contribution set exactly.
  repeated ContributionRef implemented_contributions = 6;
  repeated string plugin_features = 7;     // optional plugin RPCs implemented
}

message LoadRequest {
  LoadReason reason = 1;
  string tenant_id = 2;                    // empty for shared tenancy
  google.protobuf.Struct settings = 3;
  ReloadState previous_state = 4;          // only when reason = RELOAD and stateful
  google.protobuf.Timestamp deadline = 5;
}

enum LoadReason {
  LOAD_REASON_UNSPECIFIED = 0;
  LOAD_REASON_COLD_START = 1;
  LOAD_REASON_RELOAD = 2;
  LOAD_REASON_CRASH_RECOVERY = 3;
  LOAD_REASON_SCALE_OUT = 4;
}

message LoadResponse {
  bool previous_state_accepted = 1;
  repeated string warnings = 2;
}

message ConfigureRequest {
  google.protobuf.Struct settings = 1;
  uint64 settings_revision = 2;
  google.protobuf.Timestamp deadline = 3;
}

message ConfigureResponse {}

message MigrateConfigRequest {
  ContributionRef contribution = 1;
  uint32 from_schema_version = 2;
  uint32 to_schema_version = 3;
  google.protobuf.Struct config = 4;
}

message MigrateConfigResponse {
  google.protobuf.Struct config = 1;
  repeated string warnings = 2;
}

message PrepareReloadRequest {
  string target_plugin_version = 1;
  google.protobuf.Timestamp deadline = 2;
}

message PrepareReloadResponse {
  ReloadState state = 1;
}

// A new instance MUST reject (previous_state_accepted = false) any schema_version it does not know.
message ReloadState {
  uint32 schema_version = 1;
  string from_plugin_version = 2;
  bytes data = 3;                          // <= lifecycle.maxStateBytes
}

message UnloadRequest {
  UnloadReason reason = 1;
  google.protobuf.Timestamp deadline = 2;
}

enum UnloadReason {
  UNLOAD_REASON_UNSPECIFIED = 0;
  UNLOAD_REASON_SHUTDOWN = 1;
  UNLOAD_REASON_DISABLED = 2;
  UNLOAD_REASON_UNINSTALLED = 3;
  UNLOAD_REASON_RELOAD = 4;
  UNLOAD_REASON_IDLE = 5;
  UNLOAD_REASON_RESOURCE_PRESSURE = 6;
  UNLOAD_REASON_REVOKED = 7;               // host may kill without calling Unload
}

message UnloadResponse {}

message CheckHealthRequest {}

message CheckHealthResponse {
  HealthStatus status = 1;
  string detail = 2;
}

enum HealthStatus {
  HEALTH_STATUS_UNSPECIFIED = 0;
  HEALTH_STATUS_SERVING = 1;
  HEALTH_STATUS_DEGRADED = 2;              // stays routable; surfaced in ops dashboards
  HEALTH_STATUS_NOT_SERVING = 3;
}
```

