```proto
syntax = "proto3";

package reporting.plugin.v1;

import "google/protobuf/duration.proto";
import "google/protobuf/timestamp.proto";
import "reporting/plugin/v1/query.proto";

// Stability: stable
// Served by the host (through the local supervisor socket). Instance identity comes from
// the connection; per-invocation calls carry metadata x-rpt-capability.
// Metrics and traces use OTLP to RPT_OTLP_ENDPOINT; the collector overwrites plugin resource
// attributes from the connection identity.

service HostLogging {
  rpc EmitLogs(EmitLogsRequest) returns (EmitLogsResponse);
}

// Only names declared in permissions.secrets and bound for this tenant. Every read is audited.
service HostSecrets {
  rpc GetSecret(GetSecretRequest) returns (GetSecretResponse);
}

// Namespaced by (tenant, plugin). Keys <= 512 bytes, values <= 1 MiB, total <= kv.quotaMb.
service HostStorage {
  rpc KvGet(KvGetRequest) returns (KvGetResponse);
  rpc KvPut(KvPutRequest) returns (KvPutResponse);
  rpc KvDelete(KvDeleteRequest) returns (KvDeleteResponse);
  rpc KvList(KvListRequest) returns (KvListResponse);
}

// Requires permissions.data.query != none AND a capability token scoped to the dataset.
// Executes as the invocation principal. Same stream contract as ExecuteQuery.
service HostData {
  rpc QueryDataset(QueryDatasetRequest) returns (stream QueryDatasetResponse);
}

message EmitLogsRequest {
  repeated LogRecord records = 1;
}

message LogRecord {
  google.protobuf.Timestamp time = 1;
  LogSeverity severity = 2;
  string message = 3;
  map<string, string> attributes = 4;
  string invocation_id = 5;
  string traceparent = 6;
}

enum LogSeverity {
  LOG_SEVERITY_UNSPECIFIED = 0;
  LOG_SEVERITY_DEBUG = 1;
  LOG_SEVERITY_INFO = 2;
  LOG_SEVERITY_WARN = 3;
  LOG_SEVERITY_ERROR = 4;
}

message EmitLogsResponse {
  uint32 dropped = 1;                      // rate-limited records
}

message GetSecretRequest {
  string name = 1;
}

message GetSecretResponse {
  bytes value = 1;
  string version = 2;
  google.protobuf.Timestamp expires_at = 3;  // do not cache beyond this
}

message KvGetRequest {
  string key = 1;
}

message KvGetResponse {
  bool found = 1;
  bytes value = 2;
  uint64 revision = 3;
}

message KvPutRequest {
  string key = 1;
  bytes value = 2;
  optional uint64 expected_revision = 3;   // compare-and-set; 0 = must not exist
  google.protobuf.Duration ttl = 4;
}

message KvPutResponse {
  uint64 revision = 1;
}

message KvDeleteRequest {
  string key = 1;
  optional uint64 expected_revision = 2;
}

message KvDeleteResponse {
  bool deleted = 1;
}

message KvListRequest {
  string prefix = 1;
  string page_token = 2;
  uint32 page_size = 3;
}

message KvListResponse {
  repeated KvEntryInfo entries = 1;
  string next_page_token = 2;
}

message KvEntryInfo {
  string key = 1;
  uint64 revision = 2;
  uint64 size_bytes = 3;
}

message QueryDatasetRequest {
  string dataset_ref = 1;
  QuerySpec query = 2;
}

message QueryDatasetResponse {
  oneof payload {
    QueryHeader header = 1;
    ArrowRecordBatch batch = 2;
    QueryTrailer trailer = 3;
  }
}
