### 7.10 Browser contract: `sdk/typescript/visualization.d.ts`

```ts
/**
 * Reporting Plugin API v1: browser contract for visualization contributions.
 * @stability experimental (target stable in 1.2)
 */
import type { Table } from "apache-arrow";

export interface ApiVersion { readonly major: 1; readonly minor: number }

/** Default export of runtime.browser.entry. */
export interface BrowserPluginModule {
  /** Minimum API version this bundle needs. */
  readonly apiVersion: ApiVersion;
  /** Keys MUST equal the manifest's visualization contribution ids. */
  readonly visualizations: Readonly<Record<string, VisualizationFactory>>;
}

export type VisualizationFactory = (
  init: VisualizationInit,
  host: VisualizationHost,
) => VisualizationInstance | Promise<VisualizationInstance>;

export interface VisualizationInit {
  readonly contributionId: string;
  readonly container: HTMLElement;
  readonly size: Size;
  readonly theme: Theme;
  readonly locale: string;              // BCP 47
  readonly timeZone: string;            // IANA
  readonly options: unknown;            // validated against configSchema, already migrated
  readonly optionsSchemaVersion: number;
  readonly data: DataFrame;
  /** "static" = headless export render: no animation, call host.renderComplete(). */
  readonly mode: "interactive" | "static";
}

export interface DataFrame {
  readonly table: Table;
  readonly columns: readonly ColumnInfo[];
  /** True if the host capped rows (dataRequirements.maxRows). */
  readonly truncated: boolean;
  readonly totalRows?: number;
}

export type ColumnRole = "dimension" | "measure" | "time" | "geo" | "identifier";

export interface ColumnInfo {
  readonly name: string;
  readonly displayName: string;
  readonly role: ColumnRole;
  readonly unit?: string;
  readonly format?: string;
}

export interface Size { readonly widthPx: number; readonly heightPx: number; readonly devicePixelRatio: number }

export interface Theme {
  readonly mode: "light" | "dark";
  readonly fontFamily: string;
  readonly tokens: Readonly<Record<string, string>>;
  readonly palette: {
    readonly categorical: readonly string[];
    readonly sequential: readonly string[];
    readonly diverging: readonly string[];
  };
}

export interface VisualizationUpdate {
  readonly data?: DataFrame;
  readonly options?: unknown;
  readonly theme?: Theme;
  readonly locale?: string;
}

export interface VisualizationInstance {
  update(update: VisualizationUpdate): void | Promise<void>;
  resize(size: Size): void;
  /** Required when the manifest declares exportImage: true. */
  renderImage?(request: ImageRequest): Promise<RenderedImage>;
  /** Release listeners, timers, workers. Must be synchronous. */
  destroy(): void;
}

export interface ImageRequest {
  readonly format: "svg" | "png";
  readonly widthPx: number;
  readonly heightPx: number;
  readonly scale: number;
}

export interface RenderedImage {
  readonly mimeType: "image/svg+xml" | "image/png";
  readonly data: Blob;
  readonly altText?: string;
}

export interface VisualizationHost {
  readonly apiVersion: ApiVersion;       // negotiated
  supports(feature: string): boolean;
  /** Rate-limited to 60 events/s. Only interactions declared in the manifest are accepted. */
  emit(event: InteractionEvent): void;
  /** Static mode: MUST be called once the first complete frame is drawn (deadline 20 s). */
  renderComplete(): void;
  reportError(error: VisualizationError): void;
  log(level: "debug" | "info" | "warn" | "error", message: string, attributes?: Record<string, string>): void;
  /** Host-consistent number/date/currency formatting for the column and locale. */
  formatValue(value: unknown, column: ColumnInfo): string;
}

export interface SelectionTerm {
  readonly column: string;
  readonly values: readonly (string | number | boolean | null)[];
}

export type InteractionEvent =
  | { readonly type: "select"; readonly mode: "replace" | "toggle" | "clear"; readonly terms: readonly SelectionTerm[] }
  | { readonly type: "hover"; readonly terms: readonly SelectionTerm[] | null }
  | { readonly type: "drilldown"; readonly terms: readonly SelectionTerm[] };

export interface VisualizationError {
  readonly code: "INVALID_OPTIONS" | "UNSUPPORTED_DATA" | "RENDER_FAILED";
  readonly userMessage: string;
  readonly debugDetail?: string;
}
```

The frame bootstrap protocol (`hello` → `init` → `update` / `resize` / `ping` / `renderImage` / `destroy`, over a MessageChannel) is internal to the SDK frame runtime. Plugins never see it.

### 7.11 SDK ergonomics (TypeScript)

```ts
import { definePlugin, dataSource, PluginError } from "@acme-reporting/plugin-sdk";

export default definePlugin({
  async onLoad(ctx) {              // ctx.settings, ctx.secrets, ctx.kv, ctx.log, ctx.previousState
    this.client = await LedgerClient.connect(await ctx.secrets.get("ledger-client-credentials"));
  },
  async onPrepareReload() { return { schemaVersion: 2, data: this.cache.serialize() }; },
  async onUnload() { await this.client.close(); },

  migrateConfig: { "gl-ledger": { 2: (c) => ({ ...c, includeUnposted: false }) } },

  contributions: {
    "gl-ledger": dataSource({
      async testConnection(_req, ctx) { return { ok: await this.client.ping(ctx.signal) }; },
      async discoverSchema() { return { entities: STATIC_ENTITIES }; },
      async *executeQuery({ query }, ctx) {
        const plan = pushdown(query);                    // what the ledger API supports
        yield ctx.header(plan.schema, plan.applied);
        for await (const rows of this.client.stream(plan, { signal: ctx.signal })) {
          yield ctx.rows(rows);                          // SDK builds and splits Arrow batches
        }
        return ctx.trailer({ nextCursor: plan.cursor });
      },
    }),
  },
});
```

**What the SDK handles automatically:**
- The handshake and version negotiation.
- A startup check that implemented contributions match `plugin.json`.
- Arrow batching and splitting, and stream ordering.
- Mapping cancellation to `ctx.signal`.
- Propagating the capability token.
- Wrapping errors in `PluginError`.
- Rejecting unknown reload-state versions.
- Deprecation warnings and secret scrubbing.
- Logs, plus OTel traces and metrics.

The Python SDK mirrors this with async generators.

---

## 8. Observability and audit

**Metrics.** Every metric is labeled `plugin`, `version`, `tenant`, `contribution`, `kind`:
- `plugin_invocations_total{outcome,error_code}` and `plugin_invocation_duration_seconds`
- `plugin_instance_state_transitions_total{from,to,reason}`, `plugin_instance_restarts_total`, `plugin_cold_start_seconds`
- `plugin_memory_bytes`, `plugin_cpu_seconds_total`, `plugin_output_bytes_total`
- `plugin_host_service_calls_total{service,method,outcome}`
- `plugin_egress_connections_total{host,decision}`
- `plugin_deprecated_api_calls_total{element}`

**Traces.** Host invocation → supervisor → plugin → host services and egress, joined by `traceparent`.

**Logs.** Structured, carrying `plugin_id`, `version`, `tenant_id`, `instance_id`, `invocation_id` and `trace_id`.

**Owner access.**
- Plugin owners see metrics and error codes/reasons for every tenant.
- They see full logs only for tenants that granted support access, because logs can contain tenant data.

**Alerting.** Dashboards are provisioned automatically for each plugin, and alerts route to `publisher.oncall`.

**Audit** (append-only, visible to tenant admins):
- Install, uninstall, upgrade and rollback.
- Permission grants and revocations; secret binding changes.
- Secret reads, one record per instance per secret per minute.
- `QueryDataset` calls.
- Denied egress.
- Quarantines and revocations.

---

## 9. Performance budgets

These are targets to be confirmed by the M0 spike.

| Metric | Target |
|---|---|
| Cold start p95 (lazy activation, gVisor) | node22 < 1.5 s · python312 < 2 s · jvm21 < 4 s (use AppCDS) |
| Router + supervisor overhead per call | p50 < 3 ms, p99 < 15 ms, excluding plugin work |
| Arrow throughput through the supervisor | ≥ 200 MiB/s per stream |
| Health-check overhead | < 1% CPU per instance |

**Main cost risk:** with `perTenant`, instance count grows with the number of active (tenant, plugin) pairs. Lazy activation and idle unload keep this in check. If M0 numbers are bad, the escape valves are, in order:
1. `shared` tenancy for stateless compute, after security review.
2. The WASM tier (§6.6).

---

## 10. Developer experience

| Command | Purpose |
|---|---|
| `rpt init --kind dataSource --lang ts` | Scaffold with a manifest, SDK wiring, tests and CI config |
| `rpt validate` | Schema plus rules V1–V15, and a permission-diff preview |
| `rpt dev [--strict]` | Local host emulator: fake tenant, sample datasets, a contribution invoker, a viz playground, hot reload |
| `rpt test conformance [--strict]` | The conformance kit for the declared API version |
| `rpt pack` / `rpt publish --channel dev` | Deterministic artifact; beta and stable publish from CI only |

**Also provided:**
- HTTP record/replay fixtures for testing against upstreams.
- API reference docs generated from the protos and TS.
- A cookbook for each extension point.
- **One maintained sample plugin per extension point.** These double as the host's compatibility matrix.

---

## 11. Governance for five teams

**Ownership.**
- The platform team owns the host, API repo, SDKs, conformance kit and registry.
- Plugin teams own their plugins end to end, including on-call.

**Namespaces.** Each team has `com.acme.<team>.*` reserved, tied to its CI signing identity.

**API changes.**
- **Minor changes** go to a weekly **API council** (platform plus one rep per plugin team). They pass by lazy consensus after 5 business days.
- **New extension points and majors** need a written RFC with 2 weeks for comments.
- Every change ships with conformance tests and TS and Python SDK support in the same release.

**Cadence.** At most one API minor per month. Hosts support a minor before its SDK is released.

**Production readiness checklist:**
- Strict conformance passes.
- Owner, on-call and runbook are set.
- Every permission has a justification.
- Load-tested at the declared resources.
- `MigrateConfig` fixtures exist.
- A justification is on file if `eager`.

**Support.** A `#plugin-platform` channel and weekly office hours through the first quarter.

---

## 12. Rollout plan

The pre-quarter work matters most, because the teams start building next quarter.

| Milestone | When | Deliverables | Exit criteria |
|---|---|---|---|
| **M0: Contract RC** | Q−6w → Q−1w | Protos and manifest `1.0-rc`, TS and Python SDK alpha, `rpt dev`, conformance kit v0 (lifecycle, dataSource, exporter), sample plugins, performance spike | All five teams have reviewed the API against their planned plugins and signed off; §9 measured |
| **M1: Build** | Q+0 → Q+4w | Stable parts **frozen at Q+2w**; dev-channel registry; strict sandbox in CI | Every team has a plugin passing conformance on `dev` |
| **M2: Staging** | Q+4w → Q+8w | Production runner pool, egress proxy, signing, approval UI, observability, `beta` channel, API 1.1 based on experimental feedback | Sandbox security review and external pen test (escape, SSRF, iframe) passed; beta running on internal tenants |
| **M3: GA** | Q+8w → Q+12w | Stateful hot reload, staged rollouts, revoke kill switch, API 1.2 with all extension points stable | Revoke drill < 5 min; chaos tests (crash loops, OOM, hangs, a flood of slow calls) show no impact on the host |

**Before the freeze,** `1.0-rc.N` may break, but only with a changelog and codemods. After the freeze, §7 applies.

**Risks**

| Risk | Mitigation |
|---|---|
| Per-tenant instance cost | Lazy activation and idle unload, measured in M0; `shared` and WASM as fallbacks |
| gVisor I/O overhead hurts data-heavy connectors | Measure in M0; runc + seccomp as an approved fallback |
| API churn from first real use | RC period, experimental levels, API council |
| Non-HTTP egress to customer databases is hard to police | CONNECT/SOCKS proxy with hostname and resolved-IP checks; private networks only through an explicit tenant grant |
| Large datasets slow down iframe visualizations | Host pre-aggregation, 100k row cap, OffscreenCanvas in workers |
| Teams request broad permissions to get unblocked | Sensitive-tier review; permission diff shown on every release |

---

## 13. Open questions to settle before M0

1. **Deployment model.** This design assumes multi-tenant SaaS on Linux/Kubernetes.
   - If the tool is single-tenant or self-hosted, `perTenant` collapses and approvals get simpler.
   - If customers run hosts on-prem, revocation needs an offline path.
2. **What are the five teams actually building?** Map each plugin to an extension point. Needs that don't fit, such as custom pages, auth providers or report lifecycle hooks, should become RFCs before the freeze, not after.
3. **Languages.** Does any team need a JVM or Go SDK at M0?
4. **Third-party plugins.** Are they on the roadmap? That changes signing trust roots and the review process, not the sandbox.
5. **External assets for visualizations** (map tiles, web fonts). They are currently blocked by `connect-src 'none'`; the answer might be a host-proxied asset feature.
6. **Existing services.** Is there a secret vault and a row-level security service the broker can call, or do those need building?
7. **Data residency.** Must runner nodes stay in the tenant's region? The design assumes yes.

