// Types shared by every plugin contract. Changes here affect all contracts,
// so this package follows the strictest compatibility rules (see design doc §8).
package reporting.plugin.common.v1;

import "google/protobuf/duration.proto";
import "google/protobuf/timestamp.proto";

// Sent as the first field of every host->plugin request. Deadlines and trace
// context travel as gRPC metadata (grpc-timeout, traceparent), not here.
message CallContext {
  // Unique per logical user action; stable across retries of the same call.
  string request_id = 1;
  // Always set. Plugins must never let data from one tenant reach another.
  string tenant_id = 2;
  Principal principal = 3;
  // BCP 47 tag, e.g. "en-GB".
  string locale = 4;
  // IANA zone, e.g. "Europe/London".
  string time_zone = 5;
  string installation_id = 6;
}

message Principal {
  enum Kind {
    KIND_UNSPECIFIED = 0;
    KIND_USER = 1;
    KIND_SCHEDULE = 2;
    KIND_SYSTEM = 3;
  }
  Kind kind = 1;
  // Opaque and stable within a tenant. Safe to use as a cache key.
  string subject_id = 2;
  // Populated only when the installation grants capabilities.context.userIdentity.
  string email = 3;
  string display_name = 4;
}

// Attached to non-OK gRPC statuses as a google.rpc.Status detail.
message PluginError {
  ErrorCode code = 1;
  // Shown to end users verbatim. Must not contain secrets or stack traces.
  string user_message = 2;
  // Logged for operators only.
  string debug_message = 3;
  bool retryable = 4;
  google.protobuf.Duration retry_after = 5;
  map<string, string> metadata = 6;
}

enum ErrorCode {
  ERROR_CODE_UNSPECIFIED = 0;
  ERROR_CODE_INVALID_ARGUMENT = 1;
  ERROR_CODE_INVALID_CONFIG = 2;
  ERROR_CODE_AUTH_FAILED = 3;
  ERROR_CODE_PERMISSION_DENIED = 4;
  ERROR_CODE_NOT_FOUND = 5;
  ERROR_CODE_UPSTREAM_UNAVAILABLE = 6;
  ERROR_CODE_RATE_LIMITED = 7;
  ERROR_CODE_QUOTA_EXCEEDED = 8;
  ERROR_CODE_UNSUPPORTED = 9;
  ERROR_CODE_CANCELLED = 10;
  ERROR_CODE_DEADLINE_EXCEEDED = 11;
  ERROR_CODE_INTERNAL = 12;
}

message ContractVersion {
  // "host", "datasource", "transform", "visualization", "exporter", "delivery".
  string contract = 1;
  uint32 major = 2;
  uint32 minor = 3;
}

// An Arrow IPC-encoded schema message.
message ArrowSchema {
  bytes ipc = 1;
}

// An Arrow IPC-encoded record batch. Must conform to the schema most recently
// sent on the same stream. Hosts reject batches larger than 4 MiB encoded.
message ArrowBatch {
  bytes ipc = 1;
  int64 row_count = 2;
}

message Progress {
  // 0.0-1.0 when known; unset when the total is unknown.
  optional double fraction = 1;
  int64 rows_processed = 2;
  string message = 3;
}

message Value {
  oneof kind {
    bool null_value = 1;
    bool bool_value = 2;
    int64 int_value = 3;
    double double_value = 4;
    string string_value = 5;
    google.protobuf.Timestamp timestamp_value = 6;
    bytes bytes_value = 7;
    // Decimal as a canonical string, e.g. "-1234.5600", to avoid float loss.
    string decimal_value = 8;
  }
