// Filter expression tree. Used for datasource pushdown and visualization
// cross-filtering.
message Expr {
  oneof kind {
    ExprList all = 1;
    ExprList any = 2;
    Expr negate = 3;
    Compare compare = 4;
    InList in_list = 5;
    IsNull is_null = 6;
  }
}

message ExprList {
  repeated Expr operands = 1;
}

message Compare {
  enum Op {
    OP_UNSPECIFIED = 0;
    OP_EQ = 1;
    OP_NE = 2;
    OP_LT = 3;
    OP_LE = 4;
    OP_GT = 5;
    OP_GE = 6;
