// contract. The host is the only caller.
package reporting.plugin.lifecycle.v1;

import "google/protobuf/struct.proto";
import "google/protobuf/timestamp.proto";
import "reporting/plugin/common/v1/common.proto";

service PluginLifecycleService {
  // Always the first call on a new instance. Negotiates contract versions.
  rpc Handshake(HandshakeRequest) returns (HandshakeResponse);
  // Called exactly once, after Handshake and before any contribution call.
  rpc Load(LoadRequest) returns (LoadResponse);
  // Polled by the supervisor. Must answer within 2s and must not do I/O-heavy work.
  rpc CheckHealth(CheckHealthRequest) returns (CheckHealthResponse);
  // Installation config changed. The plugin applies it in place or asks for a reload.
  rpc UpdateConfig(UpdateConfigRequest) returns (UpdateConfigResponse);
  // Only called when the manifest sets lifecycle.statefulReload, after draining.
  rpc ExportState(ExportStateRequest) returns (ExportStateResponse);
  // Called at most once. May never be called (crash, kill, policy revocation).
  rpc Unload(UnloadRequest) returns (UnloadResponse);
}

message ContractRange {
  string contract = 1;
  uint32 major = 2;
  uint32 min_minor = 3;
  uint32 max_minor = 4;
}

message HandshakeRequest {
  string host_version = 1;
  string instance_id = 2;
  string plugin_id = 3;
  string plugin_version = 4;
  // One entry per (contract, major) the host currently serves.
  repeated ContractRange offered = 5;
}

message HandshakeResponse {
  // Exactly one entry for "host" plus one per contract the plugin contributes to.
  // Each must fall inside an offered range and inside the manifest's declared range.
  repeated reporting.plugin.common.v1.ContractVersion selected = 1;
  string sdk_name = 2;
  string sdk_version = 3;
  // Must equal the set of contribution ids declared in the manifest.
