// Services the host exposes to plugins. Part of the "host" contract.
// Deliberately small: every RPC here is attack surface and a compatibility promise.
//
// Every call is authenticated by the per-instance session token (gRPC metadata
// "x-rplug-session") and scoped by the host to (plugin id, tenant). A plugin
// cannot name another plugin or tenant in any request.
package reporting.plugin.host.v1;

import "google/protobuf/duration.proto";
import "google/protobuf/timestamp.proto";
import "reporting/plugin/common/v1/common.proto";

service HostService {
  // Resolve a {"$secretRef": "..."} handle from this plugin's own config.
  rpc GetSecret(GetSecretRequest) returns (GetSecretResponse);

  // Plugin-private key/value storage. Requires capability storage.kv.
  rpc KvGet(KvGetRequest) returns (KvGetResponse);
  rpc KvPut(KvPutRequest) returns (KvPutResponse);
  rpc KvDelete(KvDeleteRequest) returns (KvDeleteResponse);
  rpc KvList(KvListRequest) returns (KvListResponse);
}

message GetSecretRequest {
  reporting.plugin.common.v1.CallContext ctx = 1;
  string secret_ref = 2;
}

message GetSecretResponse {
  bytes value = 1;
  // SDKs cache until this time. Never persist secrets to kv or tmp.
  google.protobuf.Timestamp cache_until = 2;
}

message KvGetRequest {
  string key = 1;
}

message KvGetResponse {
  bool found = 1;
  bytes value = 2;
  int64 revision = 3;
}

message KvPutRequest {
  // At most 512 bytes.
  string key = 1;
  // At most 1 MiB.
  bytes value = 2;
  google.protobuf.Duration ttl = 3;
  // When set, the write fails with FAILED_PRECONDITION unless the current
  // revision matches. 0 means "key must not exist".
  optional int64 expected_revision = 4;
}

message KvPutResponse {
  int64 revision = 1;
}

message KvDeleteRequest {
  string key = 1;
  optional int64 expected_revision = 2;
}

message KvDeleteResponse {
  bool deleted = 1;
}

message KvListRequest {
  string prefix = 1;
  int32 page_size = 2;
  string page_token = 3;
}

message KvListResponse {
  repeated string keys = 1;
  string next_page_token = 2;
}
