}

message GetDatasetSchemaRequest {
  reporting.plugin.common.v1.CallContext ctx = 1;
  Target target = 2;
  string dataset_id = 3;
}

message GetDatasetSchemaResponse {
  reporting.plugin.common.v1.ArrowSchema schema = 1;
  repeated ParameterSpec parameters = 2;
  optional int64 estimated_row_count = 3;
