// Contract "transform", major 1. Arrow in, Arrow out. Transforms never fetch
// data themselves; the host pushes exactly the rows the transform may see.
package reporting.plugin.transform.v1;

import "google/protobuf/struct.proto";
import "reporting/plugin/common/v1/common.proto";

service TransformService {
  // Validate params and compute the output schema without data. Called at
  // report design time and before every run. Must be pure and fast (<1s).
  rpc PlanTransform(PlanTransformRequest) returns (PlanTransformResponse);
  // Bidirectional stream. Backpressure is HTTP/2 flow control: do not buffer
  // unboundedly; stop reading input when output is not being consumed.
  rpc RunTransform(stream RunTransformRequest) returns (stream RunTransformResponse);
}

message PlanTransformRequest {
  reporting.plugin.common.v1.CallContext ctx = 1;
  string contribution_id = 2;
  // Validated by the host against the contribution's paramsSchema first.
  google.protobuf.Struct params = 3;
  reporting.plugin.common.v1.ArrowSchema input_schema = 4;
}

message PlanTransformResponse {
  reporting.plugin.common.v1.ArrowSchema output_schema = 1;
  // Non-fatal issues shown in the report editor.
  repeated string warnings = 2;
}

message RunTransformStart {
  reporting.plugin.common.v1.CallContext ctx = 1;
  string contribution_id = 2;
  google.protobuf.Struct params = 3;
  reporting.plugin.common.v1.ArrowSchema input_schema = 4;
}

message EndOfInput {}

// Stream order: exactly one start, zero or more batches, exactly one end.
message RunTransformRequest {
  oneof kind {
    RunTransformStart start = 1;
    reporting.plugin.common.v1.ArrowBatch batch = 2;
    EndOfInput end = 3;
  }
}

message TransformComplete {
  int64 row_count = 1;
}

// Stream order: exactly one schema (must equal PlanTransform's output_schema),
// zero or more batches interleaved with progress, exactly one complete.
message RunTransformResponse {
  oneof kind {
    reporting.plugin.common.v1.ArrowSchema schema = 1;
    reporting.plugin.common.v1.ArrowBatch batch = 2;
    reporting.plugin.common.v1.Progress progress = 3;
    TransformComplete complete = 4;
  }
}
