// Contract "exporter", major 1. Turns a rendered report into a file (PDF, XLSX, ...).
// The host resolves all data and renders visualizations to images before export;
// exporters only lay out what they are given.
package reporting.plugin.exporter.v1;

import "google/protobuf/struct.proto";
import "google/protobuf/timestamp.proto";
import "reporting/plugin/common/v1/common.proto";

service ExporterService {
  rpc Export(stream ExportRequest) returns (stream ExportResponse);
}

message ReportMetadata {
  string report_id = 1;
  string title = 2;
  google.protobuf.Timestamp generated_at = 3;
  // Parameter display values, e.g. {"Region": "EMEA"}.
  map<string, string> parameter_labels = 4;
}

message ExportStart {
  reporting.plugin.common.v1.CallContext ctx = 1;
  string contribution_id = 2;
  // One of the contribution's declared formats[].id.
  string format_id = 3;
  // Validated against the contribution's optionsSchema.
  google.protobuf.Struct options = 4;
  ReportMetadata report = 5;
}

message Heading {
  uint32 level = 1;
  string text = 2;
}

message TextBlock {
  // CommonMark. Raw HTML is stripped by the host before sending.
  string markdown = 1;
}

message ColumnFormat {
  string column = 1;
  // ICU number/date pattern, already localized for ctx.locale.
  string pattern = 2;
  string display_name = 3;
}

message TableBegin {
  string title = 1;
  reporting.plugin.common.v1.ArrowSchema schema = 2;
  repeated ColumnFormat formats = 3;
}

message TableEnd {
  int64 row_count = 1;
}

message ImageBlock {
  // "image/png" or "image/svg+xml".
  string mime_type = 1;
  bytes data = 2;
  string alt_text = 3;
  uint32 width_px = 4;
  uint32 height_px = 5;
}

message PageBreak {}

// Blocks arrive in document order. A table is table_begin, zero or more
// table_batch, table_end, with no other blocks in between.
message ReportBlock {
  string block_id = 1;
  oneof content {
    Heading heading = 2;
    TextBlock text = 3;
    TableBegin table_begin = 4;
    reporting.plugin.common.v1.ArrowBatch table_batch = 5;
    TableEnd table_end = 6;
    ImageBlock image = 7;
    PageBreak page_break = 8;
  }
}

message EndOfReport {}

// Stream order: exactly one start, zero or more blocks, exactly one end.
message ExportRequest {
  oneof kind {
    ExportStart start = 1;
    ReportBlock block = 2;
    EndOfReport end = 3;
  }
}

message ArtifactHeader {
  string mime_type = 1;
  string file_name = 2;
}

message ArtifactComplete {
  int64 size_bytes = 1;
  // Lowercase hex. The host verifies it against the received bytes.
  string sha256 = 2;
}

