// Contract "delivery", major 1. Sends exported artifacts somewhere (email, chat,
// object storage). Delivery is at-least-once: the host retries with the same
// idempotency_key, and plugins must deduplicate on it.
package reporting.plugin.delivery.v1;

import "google/protobuf/struct.proto";
import "reporting/plugin/common/v1/common.proto";

service DeliveryService {
  // Called when a user saves a schedule. Should verify reachability and permissions
  // without sending anything visible to recipients.
  rpc ValidateTarget(ValidateTargetRequest) returns (ValidateTargetResponse);
  rpc Deliver(stream DeliverRequest) returns (DeliverResponse);
}

message ValidateTargetRequest {
  reporting.plugin.common.v1.CallContext ctx = 1;
  string contribution_id = 2;
  // Validated against the contribution's targetSchema.
  google.protobuf.Struct target = 3;
}

message ValidateTargetResponse {
  bool ok = 1;
  repeated string problems = 2;
}

message ArtifactInfo {
  string file_name = 1;
  string mime_type = 2;
  int64 size_bytes = 3;
  string sha256 = 4;
}

message DeliveryContent {
  string subject = 1;
  string body_markdown = 2;
  // Deep link back to the report in the reporting tool.
  string report_url = 3;
}

message DeliverStart {
  reporting.plugin.common.v1.CallContext ctx = 1;
  string contribution_id = 2;
  google.protobuf.Struct target = 3;
  string idempotency_key = 4;
  DeliveryContent content = 5;
  repeated ArtifactInfo artifacts = 6;
}

message ArtifactChunk {
  // Index into DeliverStart.artifacts. Artifacts are sent sequentially, in order.
  uint32 artifact_index = 1;
  bytes data = 2;
}

message EndOfArtifacts {}

// Stream order: exactly one start, chunks for each artifact in order, exactly one end.
message DeliverRequest {
  oneof kind {
    DeliverStart start = 1;
    ArtifactChunk chunk = 2;
    EndOfArtifacts end = 3;
  }
}

message RecipientResult {
  string recipient = 1;
  bool delivered = 2;
  reporting.plugin.common.v1.PluginError error = 3;
}

message DeliverResponse {
  enum Status {
    STATUS_UNSPECIFIED = 0;
    STATUS_DELIVERED = 1;
    // Handed to an asynchronous upstream. Final outcome unknown.
    STATUS_ACCEPTED = 2;
    // Some recipients failed. The host does not retry partials automatically.
    STATUS_PARTIAL = 3;
    // A previous attempt with this idempotency_key already succeeded.
    STATUS_DUPLICATE = 4;
  }
  Status status = 1;
  string external_id = 2;
  repeated RecipientResult results = 3;
}
