// Contract "visualization", major 1.
//
// Not a gRPC service. Visualizations run in a sandboxed cross-origin iframe and
// talk to the host page over window.postMessage. Each message is an Envelope in
// proto3 JSON mapping; Arrow data and snapshot images travel as transferable
// ArrayBuffers in the postMessage transfer list, referenced by buffer_index.
//
// Because the wire format is JSON, field RENAMES are breaking for this package
// (buf breaking uses WIRE_JSON for the whole module).
//
// Handshake: iframe loads -> plugin sends Hello -> host sends Init ->
// plugin sends Ready -> host sends DataUpdate -> plugin sends Rendered.
package reporting.plugin.visualization.v1;

import "google/protobuf/struct.proto";
import "reporting/plugin/common/v1/common.proto";

message Envelope {
  // Monotonic per sender.
  uint64 seq = 1;
  // Set on responses (Snapshot answers SnapshotRequest).
  uint64 reply_to = 2;
  oneof body {
    HostMessage host = 3;
    PluginMessage plugin = 4;
  }
}

message HostMessage {
  oneof kind {
    Init init = 1;
    DataUpdate data = 2;
    Size resize = 3;
    Theme theme = 4;
    ConfigChanged config = 5;
    SnapshotRequest snapshot_request = 6;
    Teardown teardown = 7;
  }
}

message PluginMessage {
  oneof kind {
    Hello hello = 1;
    Ready ready = 2;
    Rendered rendered = 3;
    Snapshot snapshot = 4;
    Interaction interaction = 5;
    ConfigPatch config_patch = 6;
    reporting.plugin.common.v1.PluginError error = 7;
  }
}

message Hello {
  // Majors/minors this bundle supports for the "visualization" contract.
  repeated uint32 supported_majors = 1;
  uint32 max_minor = 2;
  string sdk_version = 3;
}

message Size {
  uint32 width_px = 1;
  uint32 height_px = 2;
  double device_pixel_ratio = 3;
}

message Theme {
  enum Mode {
    MODE_UNSPECIFIED = 0;
    MODE_LIGHT = 1;
    MODE_DARK = 2;
  }
  Mode mode = 1;
  // Design tokens as CSS custom properties, e.g. {"--color-accent": "#3b5bdb"}.
  map<string, string> tokens = 2;
}

message Init {
  enum Mode {
    MODE_UNSPECIFIED = 0;
    // Interactive, in a dashboard.
    MODE_VIEW = 1;
    // In the report editor; config_patch messages are accepted.
    MODE_EDIT = 2;
    // Headless render for export; no animation, answer snapshot_request.
    MODE_SNAPSHOT = 3;
  }
  string contribution_id = 1;
  reporting.plugin.common.v1.ContractVersion selected = 2;
  Mode mode = 3;
  // Validated against the contribution's configSchema.
  google.protobuf.Struct config = 4;
  Theme theme = 5;
  Size size = 6;
  string locale = 7;
  string time_zone = 8;
}

message Ready {}

message RoleBinding {
  // A role declared in the manifest's dataRequirements.roles[].name.
  string role = 1;
  repeated string columns = 2;
}

message DataUpdate {
  // Index into the postMessage transfer list; the buffer is an Arrow IPC stream.
  uint32 buffer_index = 1;
  int64 row_count = 2;
  // True when the host capped rows at dataRequirements.maxRows.
  bool truncated = 3;
  repeated RoleBinding bindings = 4;
}

message ConfigChanged {
  google.protobuf.Struct config = 1;
}

message SnapshotRequest {
  // "image/png" or "image/svg+xml".
  string mime_type = 1;
  Size size = 2;
}

message Teardown {}

message Rendered {
  // Wall-clock render time, for host telemetry.
  uint32 render_ms = 1;
}

message Snapshot {
  string mime_type = 1;
  uint32 buffer_index = 2;
}

message Interaction {
  message DrillDown {
    map<string, reporting.plugin.common.v1.Value> keys = 1;
  }
  message CrossFilter {
    // Unset clears this visualization's filter.
    reporting.plugin.common.v1.Expr filter = 1;
  }
  message OpenLink {
    // The host checks this against the tenant's link allowlist before opening.
    string url = 1;
  }
  oneof kind {
    DrillDown drill_down = 1;
    CrossFilter cross_filter = 2;
    OpenLink open_link = 3;
  }
}

message ConfigPatch {
  // RFC 7396 JSON Merge Patch applied to the current config, then re-validated.
  google.protobuf.Struct merge_patch = 1;
}
