## 9. SDK surface (TypeScript; Python mirrors it)

```ts
// @reporting/plugin-sdk
import { definePlugin, dataSource, errors, arrow } from "@reporting/plugin-sdk";

export default definePlugin({
  async activate(ctx) {
    ctx.log.info("activating");
  },

  async deactivate(ctx, reason) {
    await pool?.close();
  },

  async healthCheck(ctx) {
    return { status: "ok" };
  },

  async migrateStorage(ctx, from, to) {
    if (from < 3 && to >= 3) {
      for await (const key of ctx.capabilities.kv.list({ prefix: "schema:" })) {
        const v = await ctx.capabilities.kv.get(key);
        await ctx.capabilities.kv.put(`schema:v3:${key.slice(7)}`, upgrade(v));   // expand-only
      }
    }
  },

  migrateConfig(from, to, config) {
    if (from === 1) return { ...config, authMode: "token" };
    return config;
  },

  contributions: {
    dataSources: {
      netsuite: dataSource.v1({
        async testConnection(ctx, config) {
          const token = await ctx.capabilities.secrets.read("netsuite-token");
          const res = await ctx.capabilities.http.fetch(`${config.accountUrl}/ping`, {
            headers: { Authorization: token.bearer() },
            signal: ctx.signal,
          });
          return res.ok ? { ok: true } : { ok: false, message: `HTTP ${res.status}` };
        },

        async discoverSchema(ctx, config, path) { /* ... */ },

        async plan(ctx, query, config) {
          // Accept what we can push down; return the residual for the host to apply
          return { pushed: { filter: query.filter, limit: query.limit }, residual: {} , opaque: { suiteql: build(query) } };
        },

        async *execute(ctx, plan, config) {
          yield arrow.schema(SCHEMA);
          for await (const page of fetchPages(ctx, plan.opaque.suiteql)) {
            ctx.signal.throwIfAborted();
            yield arrow.batch(SCHEMA, page);
          }
        },
      }),
    },
  },
});
```

SDK responsibilities, so plugin authors don't reimplement them:
- The handshake and verifying that contributions match the manifest (fail fast in dev).
- Mapping gRPC cancellation and deadlines to `ctx.signal`, and cancelling pending broker calls when the invocation ends.
- Heartbeat thread and watchdog cooperation.
- Arrow builders with batch-size guidance (target 16–64 MiB, emitted as the plugin yields).
- `errors.*` constructors that map to wire codes, plus wrapping unknown throws as `INTERNAL` with the stack trace sent to logs only.
- A structured logger with secret redaction and automatic trace, tenant and invocation fields.
- `rpt-plugin` CLI: `init`, `dev` (runs a local host with the `process` driver, hot reload, fake broker backed by fixtures), `validate`, `test` (conformance), `pack`, `sign`, `publish`.
- `@reporting/plugin-testkit`: an in-process fake host with capability mocks (`http` record/replay, in-memory kv/blob, fake secrets, deterministic clock) and helpers per extension point.

