      }
    },
    "dependencies": {
      "type": "object", "additionalProperties": false,
      "properties": {
        "services": {
          "type": "array",
          "items": {
            "type": "object", "additionalProperties": false, "required": ["ref", "version"],
            "properties": {
              "ref": { "$ref": "#/$defs/contributionRef" },
