// Versioning
// ─────────────────────────────────────────────────────────────────────────────

/** Highest pluginApi version implemented by the running host runtime. */
export declare const PLUGIN_API_VERSION: string;

/**
 * Optional host features a plugin can feature-detect with `ctx.api.has()`.
 * Minor versions add flags. Flags are never removed within a major version.
 * The type is open so plugins compiled against an older SDK still compile.
 */
export type Capability =
  | "report.renderImage.svg"
  | "storage.ttl"
  | (string & {});

export interface ApiInfo {
  /** Negotiated pluginApi version, e.g. "1.3.0". Always satisfies manifest `engines.pluginApi`. */
