// Shared primitives
// ─────────────────────────────────────────────────────────────────────────────

export type JsonPrimitive = string | number | boolean | null;
export type JsonValue = JsonPrimitive | JsonValue[] | { [key: string]: JsonValue };
export type JsonObject = { [key: string]: JsonValue };

export interface Disposable {
  dispose(): void | Promise<void>;
}

export interface DisposableStore {
  /** Everything added here is disposed by the host at unload, in reverse order. */
  add<T extends Disposable>(disposable: T): T;
}

export type RecordBatchStream = AsyncIterable<RecordBatch>;
export type ByteStream = AsyncIterable<Uint8Array>;

declare const callBrand: unique symbol;

/**
 * One invocation of a contribution. Created by the host only; plugins cannot
 * construct one. Host services that touch tenant data require a live CallContext,
 * which is how the host stops an instance reading tenant B's data while serving tenant A.
 */
export interface CallContext {
  readonly [callBrand]: true;
  readonly requestId: string;
  /** null only for global-scope scheduled jobs. */
  readonly tenantId: string | null;
  readonly principal: Principal;
  /** BCP 47, e.g. "de-DE". */
  readonly locale: string;
  /** IANA zone, e.g. "Europe/Berlin". */
  readonly timeZone: string;
  /** Epoch milliseconds. The host cancels the call at this instant. */
  readonly deadline: number;
  /** Aborted on deadline, client cancellation, or forced unload. */
  readonly signal: AbortSignal;
}

export type Principal =
  | { readonly kind: "user"; readonly userId: string; readonly roles: readonly string[] }
  | { readonly kind: "schedule"; readonly scheduleId: string; readonly ownerUserId: string }
  | { readonly kind: "system" };

// ─────────────────────────────────────────────────────────────────────────────
// Errors
// ─────────────────────────────────────────────────────────────────────────────

export type PluginErrorCode =
  | "INVALID_ARGUMENT"     // caller input is wrong; not retryable
  | "FAILED_PRECONDITION"  // system not in required state (e.g. KV version conflict); not retryable as-is
  | "NOT_FOUND"
  | "PERMISSION_DENIED"    // permission not granted to plugin, or upstream refused the principal
  | "UNAUTHENTICATED"      // upstream credentials missing/invalid
  | "RESOURCE_EXHAUSTED"   // quota / rate limit; retryable after retryAfterMs
  | "UNAVAILABLE"          // transient; retryable
  | "DEADLINE_EXCEEDED"
  | "CANCELLED"
  | "UNIMPLEMENTED"
  | "INTERNAL";            // bug; also used for any non-PluginError thrown

export interface PluginErrorOptions {
  /** Defaults: true for UNAVAILABLE, RESOURCE_EXHAUSTED; false otherwise. */
  retryable?: boolean;
  retryAfterMs?: number;
  /** Safe to show to end users. Without it, users see a generic message and the requestId. */
  userMessage?: string;
  /** Logged, never shown to users. Must not contain secrets or row data. */
  details?: JsonObject;
  cause?: unknown;
}

export declare class PluginError extends Error {
  constructor(code: PluginErrorCode, message: string, options?: PluginErrorOptions);
  readonly code: PluginErrorCode;
  readonly retryable: boolean;
  readonly retryAfterMs?: number;
  readonly userMessage?: string;
  readonly details?: JsonObject;
  static is(value: unknown): value is PluginError;
}

// ─────────────────────────────────────────────────────────────────────────────
// Plugin module and lifecycle hooks
// ─────────────────────────────────────────────────────────────────────────────

/** The plugin entry file must `export default definePlugin({...})`. */
export declare function definePlugin(module: PluginModule): PluginModule;

export interface PluginModule {
  /**
   * Called exactly once per instance, before any contribution call.
   * Must register every contribution declared in the manifest, and nothing else.
   * Timeout: 15 s. Throwing fails the load.
   */
  activate(ctx: PluginContext): void | Promise<void>;

  /**
   * Called once when the instance stops, after in-flight calls have drained.
   * Best-effort: NOT called on crash, OOM, or forced kill. Timeout: 10 s.
   */
  deactivate?(reason: DeactivateReason): void | Promise<void>;

  /**
   * Required when manifest `state.version` > 1. Runs with exclusive, fleet-wide
   * access to this plugin's storage before activate(). Must be idempotent:
   * a crash mid-migration re-runs it from the same fromVersion. Timeout: 10 min.
   */
  migrateState?(migration: StateMigration): Promise<void>;

  /** Polled every 30 s; timeout 2 s. Three consecutive failures restart the instance. */
  healthCheck?(): Promise<HealthStatus>;
}

export type DeactivateReason =
  | "unload"
  | "reload"
  | "disable"
  | "uninstall"
  | "idle"
  | "host-shutdown"
  | (string & {});

export interface StateMigration {
  readonly fromVersion: number;
  readonly toVersion: number;
  readonly global: KeyValueStore;
  tenants(): AsyncIterable<{ readonly tenantId: string; readonly store: KeyValueStore }>;
  readonly log: Logger;
  readonly signal: AbortSignal;
}

export type HealthStatus =
  | { readonly status: "ok" }
  | { readonly status: "degraded" | "unhealthy"; readonly message: string };

