// Plugin context (capability-scoped host services)
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Services that need a manifest permission throw PluginError("PERMISSION_DENIED")
 * when used without that permission being granted. They are never undefined.
 */
export interface PluginContext {
  readonly plugin: {
    readonly id: string;
    readonly version: string;
    readonly instanceId: string;
  };
  readonly api: ApiInfo;
  readonly register: Registrar;
  readonly config: ConfigAccess;
  readonly log: Logger;
  readonly metrics: Metrics;
  /** Requires permissions.storage. */
  readonly storage: StorageAccess;
  /** Requires permissions.secrets. */
  readonly secrets: SecretStore;
  /** Requires permissions.data. */
  readonly data: DataAccess;
  /** Requires permissions.reports.read. */
  readonly reports: ReportsAccess;
  /** Disposed by the host at unload, even if deactivate() is missing or throws. */
  readonly subscriptions: DisposableStore;
  /** Aborted when the instance starts draining. Long-lived loops must watch it. */
  readonly signal: AbortSignal;
  /** Writable per-instance scratch directory. Wiped at instance exit. Size: resources.scratchMb. */
  readonly scratchDir: string;
  /** Only APIs listed in manifest `previewApis` are present. Empty in 1.0. */
  readonly preview: PreviewApis;
}

export interface PreviewApis {}

export interface Registrar {
  dataSource<P extends JsonObject>(localId: string, provider: DataSourceProvider<P>): Disposable;
  transform<P extends JsonObject>(localId: string, provider: TransformProvider<P>): Disposable;
  visualization<P extends JsonObject>(localId: string, provider: VisualizationBackend<P>): Disposable;
  exporter<P extends JsonObject>(localId: string, provider: ExporterProvider<P>): Disposable;
  deliveryChannel<P extends JsonObject>(localId: string, provider: DeliveryChannelProvider<P>): Disposable;
  reportAction<P extends JsonObject>(localId: string, provider: ReportActionProvider<P>): Disposable;
