export interface ConfigAccess<C extends JsonObject = JsonObject> {
  /** Config of the installation that routed this call (tenant installation overrides global). */
  forCall(call: CallContext): Readonly<C>;
  /** Config of the global installation, if there is one. */
  global(): Readonly<C> | undefined;
  /**
   * Fires only when manifest `configuration.hotReload` is true.
   * Otherwise a config change reloads the instance (blue/green).
   */
  onDidChange(listener: (event: ConfigChangeEvent<C>) => void | Promise<void>): Disposable;
}

export interface ConfigChangeEvent<C extends JsonObject> {
  readonly scope: { readonly kind: "global" } | { readonly kind: "tenant"; readonly tenantId: string };
