  readonly next: Readonly<C>;
}

export type LogFields = Readonly<Record<string, JsonPrimitive>>;

/**
 * Structured logger. The runtime attaches plugin id/version/instance and, inside a
 * call, requestId/tenantId/trace ids automatically. Known secret values are redacted.
 * console.* and stdout/stderr are also captured, at level "info"/"error".
 */
export interface Logger {
  debug(message: string, fields?: LogFields): void;
  info(message: string, fields?: LogFields): void;
  warn(message: string, fields?: LogFields): void;
  error(message: string, fields?: LogFields & { readonly err?: unknown }): void;
  child(fields: LogFields): Logger;
}

export type MetricLabels = Readonly<Record<string, string>>;

/** Metric names are prefixed `plugin_<id>_`. At most 1000 series per plugin; excess are dropped. */
export interface Metrics {
  counter(name: string, options?: MetricOptions): { add(value?: number, labels?: MetricLabels): void };
  histogram(
    name: string,
    options?: MetricOptions & { readonly buckets?: readonly number[] },
  ): { record(value: number, labels?: MetricLabels): void };
  gauge(name: string, options?: MetricOptions): { set(value: number, labels?: MetricLabels): void };
