export interface MetricOptions {
  readonly description?: string;
  readonly unit?: string;
  readonly labelNames?: readonly string[];
}

export interface StorageAccess {
  /** Plugin-wide, non-tenant data. Requires "global" in permissions.storage.scopes. */
  readonly global: KeyValueStore;
  /** Scoped to call.tenantId. Requires "tenant" in permissions.storage.scopes. */
  forTenant(call: CallContext): KeyValueStore;
}

/** Keys ≤ 512 bytes UTF-8; values ≤ 1 MiB serialized. Quota: permissions.storage.quotaMb. */
export interface KeyValueStore {
  get<T extends JsonValue = JsonValue>(key: string): Promise<VersionedValue<T> | undefined>;
  /** ifVersion mismatch → PluginError("FAILED_PRECONDITION"). */
  set(
    key: string,
    value: JsonValue,
    options?: { readonly ttlSeconds?: number; readonly ifVersion?: number | "absent" },
  ): Promise<{ readonly version: number }>;
  delete(key: string, options?: { readonly ifVersion?: number }): Promise<boolean>;
  list(
    prefix: string,
    options?: { readonly cursor?: string; readonly limit?: number },
  ): Promise<{ readonly keys: readonly string[]; readonly cursor?: string }>;
}

export interface VersionedValue<T extends JsonValue> {
  readonly value: T;
  readonly version: number;
}

/** Only names declared in permissions.secrets resolve. Values are never placed in env vars. */
export interface SecretStore {
  /** A secret declared with scope "plugin". */
  get(name: string): Promise<string>;
  /** A secret declared with scope "tenant", for call.tenantId. */
  get(name: string, call: CallContext): Promise<string>;
}

/** Queries host datasets AS the call's principal. The host applies row/column security. */
export interface DataAccess {
  query(call: CallContext, request: HostQueryRequest): Promise<QueryResult>;
}

export interface HostQueryRequest {
  readonly datasetId: string;
  readonly columns?: readonly string[];
  readonly filter?: FilterExpression;
  readonly sort?: readonly SortKey[];
  readonly limit?: number;
}

export interface ReportsAccess {
  get(call: CallContext, reportId: string): Promise<ReportView>;
}

export interface ReportView {
  readonly reportId: string;
  readonly revision: number;
  readonly title: string;
  readonly ownerUserId: string;
  readonly parameters: Readonly<JsonObject>;
  readonly sections: readonly {
    readonly sectionId: string;
    readonly kind: SectionKind;
    readonly title?: string;
    /** Fully qualified contribution id, e.g. "finance-data.ledger/waterfall". */
    readonly contribution?: string;
  }[];
