export type SectionKind = "table" | "visualization" | "text" | (string & {});

// ─────────────────────────────────────────────────────────────────────────────
// Data shapes shared by contributions
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Host → plugin filter tree. For data sources, the host only sends operators listed
 * in the contribution's manifest `pushdown.filterOps`, so new operators added in
 * later minors never reach a plugin that doesn't declare them.
 */
export type FilterExpression =
  | { readonly op: "and" | "or"; readonly args: readonly FilterExpression[] }
  | { readonly op: "not"; readonly arg: FilterExpression }
  | {
      readonly op: "eq" | "neq" | "lt" | "lte" | "gt" | "gte";
      readonly column: string;
      readonly value: JsonPrimitive;
    }
  | { readonly op: "in"; readonly column: string; readonly values: readonly JsonPrimitive[] }
  | { readonly op: "isNull" | "isNotNull"; readonly column: string }
  | { readonly op: "between"; readonly column: string; readonly low: JsonPrimitive; readonly high: JsonPrimitive }
  | {
      readonly op: "contains" | "startsWith";
      readonly column: string;
      readonly value: string;
      readonly caseSensitive: boolean;
    };

export interface SortKey {
  readonly column: string;
  readonly direction: "asc" | "desc";
  readonly nulls: "first" | "last";
}

export interface QueryResult {
  readonly schema: Schema;
  readonly batches: RecordBatchStream;
  /**
   * What the producer already applied. The host applies the rest itself, so a
   * data source may decline any pushdown. Omitted fields mean "not applied".
   */
  readonly applied?: { readonly filter?: boolean; readonly sort?: boolean; readonly limit?: boolean };
}

export interface ValidationIssue {
  /** JSON Pointer into params, e.g. "/currency". */
  readonly path: string;
  readonly message: string;
  readonly severity: "error" | "warning";
}

// ─────────────────────────────────────────────────────────────────────────────
// Contributions
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Params reaching any method have already been validated against the manifest
 * paramsSchema and migrated to the current paramsVersion.
 */
export interface ContributionBase<P extends JsonObject> {
  /** Checks beyond JSON Schema (cross-field rules, remote lookups). Timeout 5 s. */
  validateParams?(params: Readonly<P>, call: CallContext): Promise<readonly ValidationIssue[]>;
  /**
   * Required when manifest paramsVersion > 1. Upgrades params saved in reports at
   * `fromVersion` to the current version. Must be pure and deterministic; the host
   * caches results and may call it in any instance.
   */
  migrateParams?(saved: JsonObject, fromVersion: number, call: CallContext): Promise<P>;
}

// Data source ---------------------------------------------------------------

export interface DataSourceProvider<P extends JsonObject> extends ContributionBase<P> {
  testConnection(connection: Connection<P>, call: CallContext): Promise<ConnectionTestResult>;
  listDatasets(
    connection: Connection<P>,
    request: { readonly search?: string; readonly cursor?: string; readonly limit: number },
    call: CallContext,
  ): Promise<{ readonly datasets: readonly DatasetSummary[]; readonly cursor?: string }>;
  describeDataset(connection: Connection<P>, datasetId: string, call: CallContext): Promise<DatasetDescriptor>;
  query(connection: Connection<P>, request: DataSourceQuery, call: CallContext): Promise<QueryResult>;
}

export interface Connection<P extends JsonObject> {
  readonly connectionId: string;
  /** paramsSchema fields marked `"x-secret": true` are absent here and present in `secrets`. */
  readonly params: Readonly<P>;
  readonly secrets: Readonly<Record<string, string>>;
}

export type ConnectionTestResult =
  | { readonly ok: true; readonly message?: string }
  | { readonly ok: false; readonly code: PluginErrorCode; readonly userMessage: string };

export interface DatasetSummary {
  readonly datasetId: string;
  readonly displayName: string;
  readonly description?: string;
}

export interface DatasetDescriptor extends DatasetSummary {
  readonly schema: Schema;
  readonly rowCountEstimate?: number;
  readonly primaryKey?: readonly string[];
}

export interface DataSourceQuery {
  readonly datasetId: string;
  /** Always present. If the manifest doesn't declare pushdown.projection, it is every column. */
  readonly columns: readonly string[];
  readonly filter?: FilterExpression;
  readonly sort?: readonly SortKey[];
  readonly limit?: number;
}

// Transform -----------------------------------------------------------------

export interface TransformProvider<P extends JsonObject> extends ContributionBase<P> {
  /** Used by the report builder for previews, without running the transform. Timeout 5 s. */
  outputSchema(inputSchema: Schema, params: Readonly<P>, call: CallContext): Promise<Schema>;
  /** Returned batches must match outputSchema(input.schema, params). */
  apply(
    input: { readonly schema: Schema; readonly batches: RecordBatchStream },
    params: Readonly<P>,
    call: CallContext,
  ): RecordBatchStream;
}

// Visualization (backend half; rendering lives in plugin-ui-api.d.ts) --------

/** Register only if the visualization needs params validation or migration. */
export interface VisualizationBackend<P extends JsonObject> extends ContributionBase<P> {}

// Exporter ------------------------------------------------------------------

export interface ExporterProvider<P extends JsonObject> extends ContributionBase<P> {
  export(snapshot: ReportSnapshot, params: Readonly<P>, call: CallContext): Promise<ExportArtifact>;
}

export interface ReportSnapshot {
  readonly reportId: string;
  readonly revision: number;
  readonly title: string;
  /** ISO-8601 instant. */
  readonly generatedAt: string;
  readonly parameters: Readonly<JsonObject>;
  readonly sections: readonly ReportSnapshotSection[];
}

export interface ReportSnapshotSection {
  readonly sectionId: string;
  readonly kind: SectionKind;
  readonly title?: string;
  /** Sanitized Markdown, for kind "text". */
  readonly text?: string;
  /** For "table" and "visualization" sections. */
  openData(): Promise<QueryResult>;
  /** For "visualization" sections; the host renders headlessly. "svg" requires capability report.renderImage.svg. */
  renderImage(options: {
    readonly format: "png" | "svg";
    readonly widthPx: number;
    readonly heightPx?: number;
    readonly scale?: number;
  }): Promise<ByteStream>;
}

export interface ExportArtifact {
  readonly fileName: string;
  /** Must equal the contribution's manifest mimeType. */
  readonly mimeType: string;
  readonly body: ByteStream;
}

// Delivery channel ----------------------------------------------------------

export interface DeliveryChannelProvider<P extends JsonObject> extends ContributionBase<P> {
  /**
   * Delivery is at-least-once. Use idempotencyKey to deduplicate on the remote side.
   * Throw a retryable PluginError for transient failures; return "rejected" for permanent ones.
   */
  deliver(request: DeliveryRequest<P>, call: CallContext): Promise<DeliveryResult>;
}

export interface DeliveryRequest<P extends JsonObject> {
  readonly idempotencyKey: string;
  /** The channel's params: where to deliver (channel id, address list, ...). */
  readonly target: Readonly<P>;
  readonly subject: string;
  readonly message?: string;
  readonly report: { readonly reportId: string; readonly title: string; readonly url: string };
  readonly attachments: readonly {
    readonly fileName: string;
    readonly mimeType: string;
    readonly sizeBytes: number;
    open(): Promise<ByteStream>;
  }[];
}

export type DeliveryResult =
  | { readonly status: "delivered"; readonly externalId?: string }
  | { readonly status: "rejected"; readonly userMessage: string };

// Report action -------------------------------------------------------------

export interface ReportActionProvider<P extends JsonObject> extends ContributionBase<P> {
  run(request: ReportActionRequest<P>, call: CallContext): Promise<ReportActionResult>;
}

export interface ReportActionRequest<P extends JsonObject> {
  readonly reportId: string;
  readonly placement: "report.toolbar" | "section.menu" | "table.row" | (string & {});
  readonly sectionId?: string;
  /** For "table.row": the row's values keyed by column name. */
  readonly selection?: JsonValue;
  readonly params: Readonly<P>;
}

export interface ReportActionResult {
  readonly notice?: { readonly level: "info" | "success" | "warning"; readonly message: string };
  /** https only; the host shows the user an "external link" notice before opening it. */
  readonly openUrl?: string;
  readonly refreshReport?: boolean;
}

// Scheduled job -------------------------------------------------------------

export interface ScheduledJobProvider {
  /**
   * At-least-once; at most one concurrent run per scope across the fleet.
   * If a run is still going when the next one is due, the next one is skipped.
   */
  run(run: ScheduledJobRun, call: CallContext): Promise<void>;
}

export interface ScheduledJobRun {
  readonly runId: string;
  /** ISO-8601 instant the run was scheduled for (not when it started). */
  readonly scheduledFor: string;
  /** 1-based. Failed runs retry up to 3 attempts with backoff. */
  readonly attempt: number;
  readonly lastSuccessfulRunAt?: string;
}
