  "license": "Proprietary",

  "engines": { "pluginApi": "^1.3" },             // needs API >=1.3.0 <2.0.0
  "runtime": { "type": "node", "runtimeVersion": "22", "entry": "dist/index.js" },
  "activation": { "mode": "lazy", "idleUnloadSeconds": 900 },

  "contributes": {
    "datasources": [{
      "name": "warehouse",
      "displayName": "Snowflake Warehouse",
      "connectionSchema": { "type": "object", "required": ["account", "warehouse"], "properties": {
        "account":   { "type": "string", "pattern": "^[a-z0-9-]+$" },
        "warehouse": { "type": "string" } } },
      "querySchema": { "type": "object", "required": ["sql"], "properties": { "sql": { "type": "string", "maxLength": 100000 } } },
      "capabilities": { "projectionPushdown": true, "filterPushdown": true, "limitPushdown": true,
