 * @reporting/plugin-api
 *
 * The versioned contract between the reporting host and plugins.
 * This package contains TYPES and thin client shims only - no host internals.
 * Plugins depend on it; the host implements it.
 *
 * Stability annotations are load-bearing and enforced by the API linter in CI:
 *
 *   @stable   - covered by the compatibility policy. Breaking change => MAJOR.
 *   @preview  - opt-in via manifest `previewFeatures`. May change in a MINOR.
 *   @deprecated(since, removeIn) - still works, warns, removed at the stated major.
 *
 * API version: 2.4.0
 */

// ---------------------------------------------------------------------------
// Versioning & capability negotiation
// ---------------------------------------------------------------------------

/** @stable since 2.0 */
export interface ApiVersion {
  readonly major: number;
  readonly minor: number;
  readonly patch: number;
  /** Wire protocol generation. Independent of the API surface version. */
  readonly protocol: number;
}

/**
 * Additive features shipped in MINOR releases are discoverable here.
 *
 * Feature-detect; do not version-sniff. A plugin declaring `engines.api: "^2.3"`
 * runs on 2.3 through 2.x, and `has()` is how it lights up 2.7 features without
 * narrowing its range and stranding users on older hosts.
 *
 * @stable since 2.0
 */
export interface CapabilitySet {
  has(feature: FeatureId): boolean;
  require(feature: FeatureId): void; // throws IncompatibleHostError
  readonly all: readonly FeatureId[];
}

/** @stable since 2.0 */
export type FeatureId =
  | 'datasource.streaming.v2'
  | 'datasource.pushdown.aggregate'
  | 'datasource.cancellation'
  | 'export.streaming'
  | 'viz.canvasWorker'
  | 'transform.vectorized'
  | 'secrets.connection'
  | 'net.http2'
  | 'storage.transactional'
  | (string & {}); // forward-compatible: unknown ids are legal and return false

// ---------------------------------------------------------------------------
// Module shape & lifecycle
// ---------------------------------------------------------------------------

/**
 * The default export of a plugin's `main` entry.
 * @stable since 2.0
 */
export interface PluginModule<TExports = unknown> {
  /**
   * Called once per activation. Register contributions here and return quickly.
   *
   * Contract:
   *  - MUST complete within `resources.activateTimeoutMs` or the instance is failed.
   *  - MUST NOT perform unbounded work; open connections lazily on first use.
   *  - MAY return an exports object, published to dependent plugins and validated
   *    against `exports` in the manifest.
   *  - Everything registered MUST be disposed via `ctx.subscriptions` or be
   *    cancellable by `ctx.signal`. The host revokes capabilities independently,
   *    but in-flight work the plugin owns is the plugin's job to stop.
   */
  activate(ctx: PluginContext): Promise<TExports | void> | TExports | void;

  /**
   * Called once per deactivation. Best-effort: the host force-terminates after
   * `resources.deactivateTimeoutMs` regardless of whether this resolves.
   *
   * Do NOT rely on this for correctness-critical cleanup - a crashed or hung
   * instance never reaches it. Anything that must survive a hard kill belongs in
   * a host-journalled transaction, not here.
   */
  deactivate?(reason: DeactivateReason): Promise<void> | void;

  /** Called when admin-visible config changes without a reload. @stable since 2.2 */
  onConfigChange?(next: Readonly<JsonObject>, prev: Readonly<JsonObject>): Promise<void> | void;
}

/** @stable since 2.0 */
export type DeactivateReason =
  | 'unload'          // explicit disable/uninstall
  | 'reload'          // will be followed by a fresh activate of a new instance
  | 'host-shutdown'
  | 'dependency-lost' // a required dependency plugin went away
  | 'quarantine'      // circuit breaker tripped
  | 'idle-eviction';  // lazily activated, unused past the idle window

// ---------------------------------------------------------------------------
// Context - the entire host surface a plugin can reach
// ---------------------------------------------------------------------------

/**
 * Capabilities are OPTIONAL properties, present only when the manifest granted
 * the matching permission. This makes the permission model type-visible: a
 * plugin that forgot to declare `net` gets a compile error, not a runtime denial.
 *
 * @stable since 2.0
 */
export interface PluginContext {
  readonly api: ApiVersion;
  readonly capabilities: CapabilitySet;
  readonly plugin: PluginIdentity;

  /** Aborted at the start of deactivation, before `deactivate()` is called. */
  readonly signal: AbortSignal;
  /** Disposed LIFO after `deactivate()` resolves or times out. */
  readonly subscriptions: Disposable[];

  readonly log: Logger;
  readonly metrics: Metrics;
  readonly registry: ExtensionRegistry;
  readonly config: ConfigStore;
  readonly storage: KeyValueStore;
  readonly host: HostBridge;

  readonly secrets?: SecretStore;   // permissions.secrets
  readonly net?: NetCapability;     // permissions.net
  readonly fs?: TempFsCapability;   // permissions.fs.temp
  readonly reports?: ReportStore;   // permissions.reports
  readonly schedules?: ScheduleApi; // permissions.schedules
}

/** @stable since 2.0 */
export interface PluginIdentity {
  readonly id: string;
  readonly version: string;
  /** Unique per activation. Changes on every reload; use it to key external state. */
  readonly instanceId: string;
  readonly isolation: 'in-process' | 'worker' | 'process' | 'wasm';
  readonly channel: 'dev' | 'signed' | 'trusted' | 'stable';
}

/** @stable since 2.0 */
export interface Disposable {
  dispose(): void | Promise<void>;
}

// ---------------------------------------------------------------------------
// Extension points
// ---------------------------------------------------------------------------

/**
 * Registration is imperative but must MATCH the manifest's declarative
 * `contributes` block. Registering a type not declared in the manifest is a
 * hard error - otherwise lazy activation would be unsound, since the host
 * advertises contributions before any code runs.
 *
 * @stable since 2.0
 */
export interface ExtensionRegistry {
  registerDataSource(type: string, provider: DataSourceProvider): Disposable;
  registerVisualization(type: string, provider: VisualizationProvider): Disposable;
  registerExporter(format: string, provider: ExporterProvider): Disposable;
  registerDestination(type: string, provider: DestinationProvider): Disposable;
  registerTransform(name: string, fn: TransformFunction): Disposable;
  registerParameterType(type: string, provider: ParameterTypeProvider): Disposable;
  registerCommand(id: string, handler: (arg?: JsonValue) => Promise<JsonValue | void>): Disposable;
}

// --- Data sources ----------------------------------------------------------

/**
 * The data plane. Note that `query` returns an async iterable of Arrow record
 * batches rather than rows: a reporting workload moves millions of rows, and
 * per-row messaging across an isolation boundary is not viable. Batches are
 * transferable, so crossing the boundary is a pointer move, not a copy.
 *
 * @stable since 2.0
 */
export interface DataSourceProvider {
  testConnection(conn: ConnectionRef, signal: AbortSignal): Promise<TestResult>;
  describe(conn: ConnectionRef, signal: AbortSignal): Promise<DatasetSchema>;

  /**
   * The host applies credit-based backpressure: it will not consume faster than
   * it can write, and the iterator is suspended when credit is exhausted.
   * Respect `signal` - the host aborts on user cancellation, deadline, and
   * deactivation.
   */
  query(req: QueryRequest, signal: AbortSignal): AsyncIterable<RecordBatch>;

  /** @stable since 2.1 - advertise via contributes.dataSources[].capabilities */
  estimateCost?(req: QueryRequest, signal: AbortSignal): Promise<CostEstimate>;
}

/** An opaque handle. Secret material is resolved host-side unless secrets:read is held. @stable since 2.0 */
export interface ConnectionRef {
  readonly id: string;
  readonly type: string;
  readonly settings: Readonly<JsonObject>;
}

/** @stable since 2.0 */
export interface QueryRequest {
  readonly queryId: string;
  readonly connection: ConnectionRef;
  readonly dataset: string;
  readonly projection?: readonly string[];
  readonly filters?: readonly Filter[];
  readonly aggregates?: readonly Aggregate[];
  readonly orderBy?: readonly SortKey[];
  readonly limit?: number;
  readonly offset?: number;
  /** Absolute epoch-ms deadline. Stop work and throw DeadlineExceededError past it. */
  readonly deadline: number;
  /** Batch rows the host prefers. Advisory. */
  readonly preferredBatchRows: number;
}

/** @stable since 2.0 */
export interface Filter {
  readonly field: string;
  readonly op: 'eq' | 'neq' | 'lt' | 'lte' | 'gt' | 'gte' | 'in' | 'nin' | 'like' | 'between' | 'isNull' | 'notNull';
  readonly value?: JsonValue;
}

/** @stable since 2.0 */
export interface Aggregate {
  readonly field: string;
  readonly fn: 'count' | 'countDistinct' | 'sum' | 'avg' | 'min' | 'max' | 'median' | 'stddev';
  readonly as: string;
}

/** @stable since 2.0 */
export interface SortKey {
  readonly field: string;
  readonly direction: 'asc' | 'desc';
  readonly nulls?: 'first' | 'last';
}

/**
 * One Arrow IPC record batch. `buffer` is transferred, not cloned; after
 * yielding it the plugin MUST NOT touch it again (it is detached).
 * @stable since 2.0
 */
export interface RecordBatch {
  /** Arrow IPC stream format, including the schema message on the first batch. */
  readonly buffer: ArrayBuffer;
  readonly rowCount: number;
  /** Set on the final batch so the host can finalize without an extra round trip. */
  readonly last?: boolean;
}

/** @stable since 2.0 */
export interface DatasetSchema {
  readonly datasets: readonly {
    readonly name: string;
    readonly label?: string;
    readonly fields: readonly FieldSchema[];
    readonly estimatedRows?: number;
  }[];
}

/** @stable since 2.0 */
export interface FieldSchema {
  readonly name: string;
  /** Arrow logical type name, e.g. 'utf8' | 'int64' | 'timestamp[ms, tz=UTC]' | 'decimal128(38,9)'. */
  readonly type: string;
  readonly nullable: boolean;
  readonly label?: string;
  readonly semantic?: 'dimension' | 'measure' | 'temporal' | 'geo' | 'id';
}

/** @stable since 2.0 */
export interface TestResult {
  readonly ok: boolean;
  readonly message?: string;
  readonly latencyMs?: number;
}

/** @stable since 2.1 */
export interface CostEstimate {
  readonly rows?: number;
  readonly bytes?: number;
  readonly currencyMicros?: number;
  readonly confidence: 'exact' | 'estimated' | 'unknown';
}

// --- Other extension points ------------------------------------------------

/** Server half of a visualization; the render half lives in the `browser` entry. @stable since 2.0 */
export interface VisualizationProvider {
  validate?(options: JsonObject, schema: DatasetSchema): Promise<ValidationResult>;
  /** Server-side rendering for scheduled PDF/PNG delivery, where no browser exists. */
  renderStatic?(req: StaticRenderRequest, signal: AbortSignal): Promise<Uint8Array>;
}

/** @stable since 2.0 */
export interface StaticRenderRequest {
  readonly options: JsonObject;
  readonly data: AsyncIterable<RecordBatch>;
  readonly width: number;
  readonly height: number;
  readonly format: 'png' | 'svg' | 'pdf';
  readonly theme: 'light' | 'dark';
}

/** @stable since 2.0 */
export interface ExporterProvider {
  /**
   * Streaming exporters yield chunks so the host can pipe to object storage
   * without materializing the whole file. Declare `streaming: true` in the manifest.
   */
  export(req: ExportRequest, signal: AbortSignal): AsyncIterable<Uint8Array>;
}

/** @stable since 2.0 */
export interface ExportRequest {
  readonly format: string;
  readonly options: JsonObject;
  readonly schema: DatasetSchema;
  readonly data: AsyncIterable<RecordBatch>;
  readonly deadline: number;
}

/** @stable since 2.0 */
export interface DestinationProvider {
  deliver(req: DeliveryRequest, signal: AbortSignal): Promise<DeliveryReceipt>;
}

/** @stable since 2.0 */
export interface DeliveryRequest {
  readonly config: JsonObject;
  readonly artifact: { readonly name: string; readonly mimeType: string; readonly bytes: AsyncIterable<Uint8Array>; readonly sizeBytes?: number };
  readonly reportId: string;
  /**
   * Stable across retries of the same logical delivery. Destinations MUST treat
   * delivery as idempotent on this key - the host retries on failure and cannot
   * distinguish "send failed" from "send succeeded, ack lost".
   */
  readonly idempotencyKey: string;
  readonly deadline: number;
}

/** @stable since 2.0 */
export interface DeliveryReceipt {
  readonly ok: boolean;
  readonly externalId?: string;
  readonly message?: string;
  /** Honoured by the host's retry scheduler. */
  readonly retryAfterMs?: number;
}

/**
 * Vectorized over an Arrow batch, not called per row. A scalar-per-row hook
 * would dominate query time for any non-trivial report.
 * @stable since 2.0
 */
